CREATE OR REPLACE FUNCTION private.after_catch_present()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare
  first_species boolean;
  first_shiny boolean;
  species_name text;
begin
  if new.user_id is null then
    return new;
  end if;
  if coalesce(new.obtained_method, '') = 'ADMIN_QA'
     or coalesce(new.source_key, '') like 'admin:%' then
    return new;
  end if;
  if new.round_id is not null and private.round_is_test(new.round_id) then
    return new;
  end if;

  select coalesce(s.name, 'Pokémon') into species_name
    from public.species s
   where s.dex = new.dex;
  species_name := coalesce(species_name, coalesce(new.name, 'Pokémon'));

  select not exists (
    select 1 from public.catches where user_id = new.user_id and dex = new.dex and id <> new.id
  ) into first_species;

  if first_species then
    perform private.push_notice(
      new.user_id, 'pokedex',
      'New Pokédex Entry!',
      species_name,
      jsonb_build_object(
        'species', new.dex,
        'variant', coalesce(new.variant, 'normal'),
        'gender', coalesce(new.gender, ''),
        'shiny', coalesce(new.variant, '') like '%shiny%',
        'source', 'capture'
      )
    );
    return new;
  end if;

  if coalesce(new.variant, '') like '%shiny%' then
    select not exists (
      select 1 from public.catches
       where user_id = new.user_id and dex = new.dex and id <> new.id
         and coalesce(variant, '') like '%shiny%'
    ) into first_shiny;
    if first_shiny then
      perform private.push_notice(
        new.user_id, 'pokedex',
        'Shiny registered',
        species_name,
        jsonb_build_object(
          'species', new.dex,
          'variant', coalesce(new.variant, 'shiny'),
          'gender', coalesce(new.gender, ''),
          'shiny', true,
          'source', 'capture'
        )
      );
    end if;
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.after_catch_xp()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare
  cfg jsonb := private.progression_config();
  first_species boolean;
  first_female boolean;
  first_shiny boolean;
  catch_rate int;
  pay int;
begin
  if coalesce(new.obtained_method, '') = 'ADMIN_QA'
     or coalesce(new.source_key, '') like 'admin:%' then
    perform private.mark_seen(new.user_id, new.dex, new.pokemon_form_id);
    return new;
  end if;
  if private.round_is_test(new.round_id) then
    return new;
  end if;
  perform private.mark_seen(new.user_id, new.dex, new.pokemon_form_id);
  perform private.ensure_inventory(new.user_id);
  perform private.ensure_trainer_stats(new.user_id);
  if new.round_id is not null then
    perform private.register_capture_collection(new);
  end if;
  perform private.grant_xp(
    new.user_id, coalesce((cfg->>'catchXp')::int, 10), 'CAPTURE', 'Successful catch',
    jsonb_build_object('idempotency', 'xp-catch:' || new.id::text)
  );
  select not exists (
    select 1 from public.catches where user_id = new.user_id and dex = new.dex and id <> new.id
  ) into first_species;
  if first_species then
    perform private.grant_xp(
      new.user_id, coalesce((cfg->>'newDexXp')::int, 25), 'NEW_DEX', 'New Pokédex species',
      jsonb_build_object('idempotency', 'xp-dex:' || new.user_id::text || ':' || new.dex::text)
    );
    update public.trainer_stats
       set first_pokemon_dex = coalesce(first_pokemon_dex, new.dex), updated_at = now()
     where user_id = new.user_id;
  end if;
  if new.gender = 'Female' and new.dex = any (private.female_visual_dex()) then
    select not exists (
      select 1 from public.catches
       where user_id = new.user_id and dex = new.dex and id <> new.id
         and (gender = 'Female' or variant like '%female%')
    ) into first_female;
    if first_female then
      perform private.grant_xp(
        new.user_id, coalesce((cfg->>'firstFemaleXp')::int, 5), 'FIRST_FEMALE', 'First female variant',
        jsonb_build_object('idempotency', 'xp-female:' || new.user_id::text || ':' || new.dex::text)
      );
    end if;
  end if;
  if new.variant like '%shiny%' then
    select not exists (
      select 1 from public.catches
       where user_id = new.user_id and dex = new.dex and id <> new.id and variant like '%shiny%'
    ) into first_shiny;
    if first_shiny then
      perform private.grant_xp(
        new.user_id, coalesce((cfg->>'shinyXp')::int, 50), 'SHINY', 'First shiny of this species',
        jsonb_build_object('idempotency', 'xp-shiny:' || new.user_id::text || ':' || new.dex::text)
      );
      update public.trainer_stats
         set first_shiny_dex = coalesce(first_shiny_dex, new.dex), updated_at = now()
       where user_id = new.user_id;
    end if;
  end if;
  select s.catch_rate into catch_rate from public.species s where s.dex = new.dex;
  if exists (select 1 from public.species s where s.dex = new.dex and s.is_legendary) then
    pay := coalesce((cfg->>'legendaryXp')::int, 25);
  elsif coalesce(catch_rate, 255) <= 9 then
    pay := coalesce((cfg->>'ultraRareXp')::int, 15);
  elsif coalesce(catch_rate, 255) <= 25 then
    pay := coalesce((cfg->>'veryRareXp')::int, 10);
  elsif coalesce(catch_rate, 255) <= 75 then
    pay := coalesce((cfg->>'rareXp')::int, 5);
  else
    pay := 0;
  end if;
  if pay > 0 then
    perform private.grant_xp(
      new.user_id, pay, 'RARITY', 'Rare capture bonus',
      jsonb_build_object('idempotency', 'xp-rare:' || coalesce(new.id::text, new.dex::text))
    );
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.assert_streamlink_legal(p_mon jsonb, p_ctx text, p_hidden_auth uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  errors text[] := ARRAY[]::text[];
  v_build text;
  v_form_id int;
  v_dex int;
  form private.ref_forms%ROWTYPE;
  spec private.ref_species%ROWTYPE;
  v_nature_id int;
  v_ability_id int;
  v_ability_slot text;
  v_level int;
  v_friendship int;
  v_hp_max int;
  v_hp_cur int;
  ev_hp int; ev_atk int; ev_def int; ev_spa int; ev_spd int; ev_spe int;
  iv_hp int; iv_atk int; iv_def int; iv_spa int; iv_spd int; iv_spe int;
  gender text;
  slot jsonb;
  v_move_id int;
  v_vg text;
  v_method text;
  v_pp int;
  v_pp_max int;
  pin_pp int;
  v_learn_level int;
  n_slots int;
  seen int[] := ARRAY[]::int[];
  evs jsonb;
  ivs jsonb;
  v_digest bytea;
BEGIN
  IF p_ctx IS NULL OR p_ctx NOT IN (
    'generate', 'catch', 'grant', 'event', 'evolve', 'trade', 'edit', 'rebuild'
  ) THEN
    errors := array_append(errors, 'bad-ctx');
  END IF;
  IF p_mon IS NULL OR jsonb_typeof(p_mon) IS DISTINCT FROM 'object' THEN
    RETURN jsonb_build_object('ok', false, 'errors', jsonb_build_array('bad-mon'));
  END IF;
  IF coalesce(p_mon->>'protectedAccount', 'false') IN ('true', 't', '1') AND p_ctx = 'edit' THEN
    errors := array_append(errors, 'protected-account');
  END IF;

  v_build := p_mon->>'contentBuild';
  IF v_build IS NULL OR btrim(v_build) = '' OR jsonb_typeof(p_mon->'contentBuild') IS DISTINCT FROM 'string' THEN
    RETURN jsonb_build_object('ok', false, 'errors', jsonb_build_array('legacy-row'));
  END IF;
  IF NOT EXISTS (SELECT 1 FROM private.ref_meta m WHERE m.content_build = v_build) THEN
    errors := array_append(errors, 'unknown-pin');
  END IF;
  IF coalesce(p_mon->>'rulesetId', '') IS DISTINCT FROM 'streamlink-gen9-xgen' THEN
    errors := array_append(errors, 'bad-ruleset');
  END IF;

  v_form_id := private.streamlink_json_int(p_mon->'formId');
  IF p_mon->'formId' IS NULL THEN
    errors := array_append(errors, 'missing-form-id');
  ELSIF v_form_id IS NULL THEN
    errors := array_append(errors, 'bad-form-id');
  END IF;
  v_dex := private.streamlink_json_int(p_mon->'dex');
  IF p_mon->'dex' IS NULL THEN
    errors := array_append(errors, 'missing-dex');
  ELSIF v_dex IS NULL THEN
    errors := array_append(errors, 'bad-dex');
  END IF;
  v_level := private.streamlink_json_int(p_mon->'level');
  IF p_mon->'level' IS NULL THEN
    errors := array_append(errors, 'missing-level');
  ELSIF v_level IS NULL OR v_level < 1 OR v_level > 100 THEN
    errors := array_append(errors, 'bad-level');
  END IF;
  v_nature_id := private.streamlink_json_int(p_mon->'natureId');
  IF p_mon->'natureId' IS NULL THEN
    errors := array_append(errors, 'missing-nature');
  ELSIF v_nature_id IS NULL THEN
    errors := array_append(errors, 'bad-nature');
  END IF;
  v_ability_id := private.streamlink_json_int(p_mon->'abilityId');
  IF p_mon->'abilityId' IS NULL THEN
    errors := array_append(errors, 'missing-ability');
  ELSIF v_ability_id IS NULL THEN
    errors := array_append(errors, 'bad-ability');
  END IF;
  v_friendship := private.streamlink_json_int(p_mon->'friendship');
  IF p_mon->'friendship' IS NULL THEN
    errors := array_append(errors, 'missing-friendship');
  ELSIF v_friendship IS NULL OR v_friendship < 0 OR v_friendship > 255 THEN
    errors := array_append(errors, 'friendship');
  END IF;

  IF v_form_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'errors', to_jsonb(errors));
  END IF;

  SELECT * INTO form FROM private.ref_forms f WHERE f.content_build = v_build AND f.form_id = v_form_id;
  IF NOT FOUND THEN
    errors := array_append(errors, 'unknown-form');
    RETURN jsonb_build_object('ok', false, 'errors', to_jsonb(errors));
  END IF;
  IF v_dex IS DISTINCT FROM form.dex THEN
    errors := array_append(errors, 'form-dex-mismatch');
  END IF;
  SELECT * INTO spec FROM private.ref_species s WHERE s.content_build = v_build AND s.dex = form.dex;
  IF NOT FOUND THEN
    errors := array_append(errors, 'unknown-species');
  END IF;
  IF form.learnset_status IS DISTINCT FROM 'resolved' OR form.learnset_version_group IS NULL THEN
    errors := array_append(errors, 'unresolved-learnset');
  END IF;
  IF private.streamlink_form_blocked(v_build, v_form_id) THEN
    errors := array_append(errors, 'g1-c1-blocked');
  END IF;
  IF p_ctx IS NOT NULL AND NOT private.streamlink_obtain_ok(v_build, p_ctx, v_form_id) THEN
    errors := array_append(errors, 'obtain-denied');
  END IF;

  IF v_nature_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM private.ref_natures n WHERE n.content_build = v_build AND n.id = v_nature_id
  ) THEN
    errors := array_append(errors, 'bad-nature');
  END IF;

  v_ability_slot := p_mon->>'abilitySlot';
  IF p_mon->'abilitySlot' IS NULL OR jsonb_typeof(p_mon->'abilitySlot') IS DISTINCT FROM 'string' THEN
    errors := array_append(errors, 'missing-ability-slot');
  ELSIF v_ability_slot NOT IN ('1', '2', 'hidden') THEN
    errors := array_append(errors, 'bad-ability-slot');
  ELSIF v_ability_id IS NULL OR NOT EXISTS (
    SELECT 1 FROM private.ref_form_abilities a
    WHERE a.content_build = v_build AND a.form_id = v_form_id
      AND a.slot = v_ability_slot AND a.ability_id = v_ability_id
  ) THEN
    errors := array_append(errors, 'illegal-ability');
  ELSIF v_ability_slot = 'hidden' THEN
    v_digest := private.streamlink_specimen_digest(p_mon);
    IF p_ctx NOT IN ('grant', 'event') OR p_hidden_auth IS NULL OR v_digest IS NULL THEN
      errors := array_append(errors, 'hidden-not-authorized');
    ELSIF NOT EXISTS (
      SELECT 1 FROM private.streamlink_hidden_tickets t
      WHERE t.ticket_id = p_hidden_auth
        AND t.content_build = v_build
        AND t.form_id = v_form_id
        AND t.ctx = p_ctx
        AND t.redeemed_at IS NOT NULL
        AND t.specimen_digest IS NOT NULL
        AND t.specimen_digest = v_digest
    ) THEN
      errors := array_append(errors, 'hidden-not-authorized');
    END IF;
  END IF;

  gender := CASE WHEN jsonb_typeof(p_mon->'gender') = 'string' THEN p_mon->>'gender' ELSE NULL END;
  IF spec.gender_rate IS NOT NULL THEN
    IF spec.gender_rate = -1 AND gender IS DISTINCT FROM 'Genderless' THEN
      errors := array_append(errors, 'gender');
    ELSIF spec.gender_rate = 0 AND gender IS DISTINCT FROM 'Male' THEN
      errors := array_append(errors, 'gender');
    ELSIF spec.gender_rate = 8 AND gender IS DISTINCT FROM 'Female' THEN
      errors := array_append(errors, 'gender');
    ELSIF spec.gender_rate NOT IN (-1, 0, 8) AND gender NOT IN ('Male', 'Female') THEN
      errors := array_append(errors, 'gender');
    END IF;
  END IF;

  ivs := p_mon->'ivs';
  IF ivs IS NULL THEN
    errors := array_append(errors, 'missing-ivs');
  ELSIF jsonb_typeof(ivs) IS DISTINCT FROM 'object' THEN
    errors := array_append(errors, 'bad-ivs');
  ELSE
    iv_hp := private.streamlink_json_int(ivs->'hp');
    iv_atk := private.streamlink_json_int(ivs->'atk');
    iv_def := private.streamlink_json_int(ivs->'def');
    iv_spa := private.streamlink_json_int(ivs->'spa');
    iv_spd := private.streamlink_json_int(ivs->'spd');
    iv_spe := private.streamlink_json_int(ivs->'spe');
    IF ivs->'hp' IS NULL OR ivs->'atk' IS NULL OR ivs->'def' IS NULL
       OR ivs->'spa' IS NULL OR ivs->'spd' IS NULL OR ivs->'spe' IS NULL THEN
      errors := array_append(errors, 'missing-iv');
    ELSIF iv_hp IS NULL OR iv_atk IS NULL OR iv_def IS NULL
       OR iv_spa IS NULL OR iv_spd IS NULL OR iv_spe IS NULL THEN
      errors := array_append(errors, 'bad-iv');
    ELSIF iv_hp NOT BETWEEN 0 AND 31 OR iv_atk NOT BETWEEN 0 AND 31
       OR iv_def NOT BETWEEN 0 AND 31 OR iv_spa NOT BETWEEN 0 AND 31
       OR iv_spd NOT BETWEEN 0 AND 31 OR iv_spe NOT BETWEEN 0 AND 31 THEN
      errors := array_append(errors, 'iv-range');
    END IF;
  END IF;

  evs := p_mon->'evs';
  IF evs IS NULL THEN
    errors := array_append(errors, 'missing-evs');
  ELSIF jsonb_typeof(evs) IS DISTINCT FROM 'object' THEN
    errors := array_append(errors, 'bad-evs');
  ELSE
    ev_hp := private.streamlink_json_int(evs->'hp');
    ev_atk := private.streamlink_json_int(evs->'atk');
    ev_def := private.streamlink_json_int(evs->'def');
    ev_spa := private.streamlink_json_int(evs->'spa');
    ev_spd := private.streamlink_json_int(evs->'spd');
    ev_spe := private.streamlink_json_int(evs->'spe');
    IF evs->'hp' IS NULL OR evs->'atk' IS NULL OR evs->'def' IS NULL
       OR evs->'spa' IS NULL OR evs->'spd' IS NULL OR evs->'spe' IS NULL THEN
      errors := array_append(errors, 'missing-ev');
    ELSIF ev_hp IS NULL OR ev_atk IS NULL OR ev_def IS NULL
       OR ev_spa IS NULL OR ev_spd IS NULL OR ev_spe IS NULL THEN
      errors := array_append(errors, 'bad-ev');
    ELSIF ev_hp NOT BETWEEN 0 AND 252 OR ev_atk NOT BETWEEN 0 AND 252
       OR ev_def NOT BETWEEN 0 AND 252 OR ev_spa NOT BETWEEN 0 AND 252
       OR ev_spd NOT BETWEEN 0 AND 252 OR ev_spe NOT BETWEEN 0 AND 252 THEN
      errors := array_append(errors, 'ev-range');
    ELSIF ev_hp + ev_atk + ev_def + ev_spa + ev_spd + ev_spe > 510 THEN
      errors := array_append(errors, 'ev-total');
    END IF;
  END IF;

  IF p_mon ? 'heldItem' AND jsonb_typeof(p_mon->'heldItem') IS DISTINCT FROM 'null'
     AND coalesce(p_mon->>'heldItem', '') <> '' THEN
    errors := array_append(errors, 'held-item');
  END IF;

  IF p_mon->'moveSlots' IS NULL THEN
    errors := array_append(errors, 'missing-move-slots');
  ELSIF jsonb_typeof(p_mon->'moveSlots') IS DISTINCT FROM 'array' THEN
    errors := array_append(errors, 'bad-move-slots');
  ELSE
    n_slots := jsonb_array_length(p_mon->'moveSlots');
    IF n_slots > 4 THEN
      errors := array_append(errors, 'too-many-moves');
    END IF;
    FOR slot IN SELECT value FROM jsonb_array_elements(p_mon->'moveSlots')
    LOOP
      IF jsonb_typeof(slot) IS DISTINCT FROM 'object' THEN
        errors := array_append(errors, 'bad-move-slot');
        CONTINUE;
      END IF;
      v_move_id := private.streamlink_json_int(slot->'moveId');
      IF slot->'moveId' IS NULL THEN
        errors := array_append(errors, 'missing-move-id');
        CONTINUE;
      ELSIF v_move_id IS NULL THEN
        errors := array_append(errors, 'bad-move-id');
        CONTINUE;
      END IF;
      IF v_move_id = ANY (seen) THEN
        errors := array_append(errors, 'duplicate-move');
      ELSE
        seen := array_append(seen, v_move_id);
      END IF;
      IF jsonb_typeof(slot->'method') IS DISTINCT FROM 'string'
         OR coalesce(slot->>'method', '') = '' THEN
        errors := array_append(errors, 'missing-move-method');
        CONTINUE;
      END IF;
      v_method := slot->>'method';
      IF v_method NOT IN ('level-up', 'machine', 'egg', 'tutor') THEN
        errors := array_append(errors, 'illegal-move-method');
        CONTINUE;
      END IF;
      v_vg := CASE WHEN jsonb_typeof(slot->'versionGroup') = 'string' THEN slot->>'versionGroup' ELSE NULL END;
      IF v_vg IS DISTINCT FROM form.learnset_version_group THEN
        errors := array_append(errors, 'move-vg');
      END IF;
      v_pp := private.streamlink_json_int(slot->'pp');
      v_pp_max := private.streamlink_json_int(slot->'ppMax');
      SELECT m.pp INTO pin_pp
      FROM private.ref_moves m
      WHERE m.content_build = v_build AND m.move_id = v_move_id;
      IF pin_pp IS NULL THEN
        errors := array_append(errors, 'unknown-move');
        CONTINUE;
      END IF;
      IF v_pp_max IS DISTINCT FROM pin_pp OR v_pp IS NULL OR v_pp <= 0 OR v_pp > pin_pp THEN
        errors := array_append(errors, 'pp');
      END IF;
      v_learn_level := NULL;
      SELECT l.level INTO v_learn_level
      FROM private.ref_learnsets l
      WHERE l.content_build = v_build AND l.form_id = v_form_id
        AND l.version_group = form.learnset_version_group
        AND l.move_id = v_move_id
        AND l.method = v_method
      ORDER BY l.level
      LIMIT 1;
      IF NOT FOUND THEN
        errors := array_append(errors, 'illegal-move');
      ELSIF v_method = 'level-up' AND (v_level IS NULL OR v_learn_level > v_level) THEN
        errors := array_append(errors, 'overlevel-move');
      END IF;
    END LOOP;
  END IF;

  IF p_mon->'hpMax' IS NULL THEN
    errors := array_append(errors, 'missing-hp-max');
  ELSIF private.streamlink_json_int(p_mon->'hpMax') IS NULL THEN
    errors := array_append(errors, 'bad-hp-max');
  END IF;
  IF p_mon->'hpCurrent' IS NULL THEN
    errors := array_append(errors, 'missing-hp-current');
  ELSIF private.streamlink_json_int(p_mon->'hpCurrent') IS NULL THEN
    errors := array_append(errors, 'bad-hp-current');
  END IF;
  IF form.hp IS NOT NULL AND iv_hp IS NOT NULL AND ev_hp IS NOT NULL AND v_level IS NOT NULL
     AND private.streamlink_json_int(p_mon->'hpMax') IS NOT NULL THEN
    v_hp_max := private.streamlink_hp_max(form.hp, iv_hp, ev_hp, v_level);
    IF private.streamlink_json_int(p_mon->'hpMax') IS DISTINCT FROM v_hp_max THEN
      errors := array_append(errors, 'hp-max');
    END IF;
    IF private.streamlink_json_int(p_mon->'hpCurrent') IS NOT NULL THEN
      v_hp_cur := private.streamlink_json_int(p_mon->'hpCurrent');
      IF v_hp_cur < 0 OR v_hp_cur > v_hp_max THEN
        errors := array_append(errors, 'hp-current');
      END IF;
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'ok', array_length(errors, 1) IS NULL,
    'errors', to_jsonb(coalesce(errors, ARRAY[]::text[]))
  );
EXCEPTION WHEN others THEN
  RETURN jsonb_build_object('ok', false, 'errors', jsonb_build_array('malformed-json'));
END
$function$

CREATE OR REPLACE FUNCTION private.catches_before_write()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if tg_op = 'INSERT' then
    if new.id is null then
      new.id := gen_random_uuid();
    end if;
    new.is_alpha := (abs(hashtext(new.id::text || 'alpha')) % 128) = 0;
  end if;
  new := private.stamp_catch_row(new);
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.freeze_catch_server_inserted_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
BEGIN
  IF NEW.server_inserted_at IS DISTINCT FROM OLD.server_inserted_at THEN
    RAISE EXCEPTION 'server insertion time is immutable' USING ERRCODE = '55000';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION private.settle_if_needed(r encounter_rounds)
 RETURNS encounter_rounds
 LANGUAGE plpgsql
AS $function$
DECLARE
  rec public.encounter_players%ROWTYPE;
  cfg jsonb;
  calc jsonb;
  bait_count int;
  player_count int;
  owns boolean;
  v_odds numeric;
  v_roll numeric;
  v_caught boolean;
  pending boolean;
  clk timestamptz;
  join_at timestamptz;
  prepare_at timestamptz;
  throw_at timestamptz;
  reveal_at timestamptz;
  throw_line text;
  who text;
  species text;
  test_out text;
  form_id int;
  v_level int;
  v_mat jsonb;
  v_catch_id uuid;
  v_life text;
BEGIN
  IF r IS NULL OR r.cancelled THEN RETURN r; END IF;
  IF r.paused_at IS NOT NULL THEN RETURN r; END IF;
  IF NOT pg_try_advisory_xact_lock(hashtextextended(r.id::text, 0)) THEN RETURN r; END IF;
  SELECT * INTO r FROM public.encounter_rounds WHERE id = r.id;
  IF r IS NULL OR r.cancelled OR r.paused_at IS NOT NULL THEN RETURN r; END IF;
  SELECT EXISTS (SELECT 1 FROM public.encounter_players ep WHERE ep.round_id = r.id AND ep.result IS NULL) INTO pending;
  IF pending = false AND r.resolved THEN RETURN r; END IF;
  clk := now();
  form_id := private.canonical_form_id(r.dex, coalesce(r.pokemon_form_id, r.dex));
  species := coalesce(nullif(btrim(r.name), ''), private.form_display_name(r.dex, form_id), 'the Pokémon');
  IF r.deadlines IS NOT NULL THEN
    join_at := (r.deadlines->>'join')::timestamptz;
    prepare_at := (r.deadlines->>'prepare')::timestamptz;
    throw_at := coalesce((r.deadlines->>'throw')::timestamptz, (r.deadlines->>'reveal')::timestamptz);
    reveal_at := (r.deadlines->>'reveal')::timestamptz;
  END IF;
  IF join_at IS NOT NULL AND clk >= join_at THEN
    IF NOT EXISTS (SELECT 1 FROM public.encounter_players WHERE round_id = r.id) THEN
      INSERT INTO public.play_console_log (round_id, kind, message)
      SELECT r.id, 'cancelled', 'No Trainers joined the encounter. The wild ' || species || ' wandered away!'
      WHERE NOT EXISTS (SELECT 1 FROM public.play_console_log l WHERE l.round_id = r.id AND l.kind = 'cancelled')
      ON CONFLICT DO NOTHING;
      UPDATE public.encounter_rounds SET cancelled = true, hidden = true, phase = 'closed', resolved = true, paused_at = null,
        last_action = 'No Trainers joined. The wild ' || species || ' wandered away!', updated_at = now() WHERE id = r.id RETURNING * INTO r;
      RETURN r;
    END IF;
    PERFORM private.phase_banner(r.id, 'prepare', 'Trainers are preparing their items…');
  END IF;
  IF prepare_at IS NOT NULL AND clk >= prepare_at THEN
    PERFORM private.phase_banner(r.id, 'throw', 'Trainers are choosing their Poké Balls!');
  END IF;
  IF r.deadlines IS NOT NULL THEN
    IF throw_at IS NOT NULL AND clk < throw_at THEN RETURN r; END IF;
  ELSIF private.round_phase(r) IN ('join', 'prepare', 'throw') THEN
    RETURN r;
  END IF;
  throw_line := private.announce_throws(r.id);
  IF throw_line IS NOT NULL THEN
    UPDATE public.encounter_rounds SET last_action = throw_line, updated_at = now() WHERE id = r.id RETURNING * INTO r;
  END IF;
  IF reveal_at IS NOT NULL AND clk < reveal_at THEN RETURN r; END IF;
  IF r.deadlines IS NULL AND private.round_phase(r) = 'reveal' THEN RETURN r; END IF;
  cfg := private.capture_config();
  test_out := CASE
    WHEN coalesce(r.trigger_source, '') = 'TEST' THEN nullif(btrim(coalesce(r.rules->>'testOutcome', '')), '')
    ELSE NULL
  END;
  SELECT count(*)::int, count(*) FILTER (WHERE prep = 'bait')::int INTO player_count, bait_count FROM public.encounter_players WHERE round_id = r.id;
  FOR rec IN SELECT * FROM public.encounter_players WHERE round_id = r.id AND result IS NULL FOR UPDATE LOOP
    who := coalesce(private.trainer_label(rec.user_id), 'A trainer');
    IF rec.ball IS NULL OR rec.result_reason = 'no_ball_left' THEN
      UPDATE public.encounter_players ep SET result = 'No throw', caught = false, result_reason = coalesce(ep.result_reason, 'no_ball')
      WHERE ep.round_id = rec.round_id AND ep.user_id = rec.user_id;
      CONTINUE;
    END IF;
    SELECT EXISTS (SELECT 1 FROM public.catches c WHERE c.user_id = rec.user_id AND c.dex = r.dex) INTO owns;
    cfg := private.capture_config() || jsonb_build_object(
      '_context', private.capture_throw_context(r, rec.user_id, rec.ball_at)
    );
    calc := private.capture_chance(r.dex, rec.ball, CASE WHEN rec.prep = 'bait' THEN NULL ELSE rec.prep END, bait_count, player_count, rec.prep = 'bait', owns, private.variant_is_shiny(r.variant), 1.0, clk, cfg);
    v_odds := (calc->>'finalChance')::numeric;
    IF test_out = 'catch' THEN
      v_roll := 0; v_caught := true;
    ELSIF test_out = 'escape' THEN
      v_roll := 1; v_caught := false;
    ELSIF coalesce((calc->>'guaranteed')::boolean, false) THEN
      v_roll := 0; v_caught := true;
    ELSE
      v_roll := private.secure_random(); v_caught := v_roll < v_odds;
    END IF;
    UPDATE public.encounter_players ep SET chance = v_odds, roll = v_roll, caught = v_caught, result = CASE WHEN v_caught THEN 'Caught' ELSE 'Escaped' END, result_reason = CASE WHEN v_caught THEN 'caught' ELSE 'escaped' END WHERE ep.round_id = rec.round_id AND ep.user_id = rec.user_id;
    INSERT INTO public.capture_log (round_id, user_id, dex, species_name, variant, gender, is_shiny, is_female, canonical_catch_rate, base_chance, ball_key, ball_multiplier, ball_condition_met, berry_key, berry_multiplier, honey_contributors, honey_participants, honey_multiplier, honey_contributor_multiplier, shiny_multiplier, event_multiplier, other_multiplier, raw_chance, final_chance, capture_roll, success, detail)
    VALUES (r.id, rec.user_id, r.dex, r.name, r.variant, r.gender, private.variant_is_shiny(r.variant), r.gender = 'Female', (calc->>'catchRate')::int, (calc->>'baseChance')::numeric, calc->'ball'->>'key', (calc->'ball'->>'multiplier')::numeric, (calc->'ball'->>'conditionMet')::boolean, calc->'berry'->>'key', (calc->'berry'->>'multiplier')::numeric, (calc->'honey'->>'contributors')::int, (calc->'honey'->>'participants')::int, (calc->'honey'->>'multiplier')::numeric, (calc->>'honeyContributorMultiplier')::numeric, (calc->>'shinyMultiplier')::numeric, (calc->>'eventMultiplier')::numeric, (calc->>'otherMultiplier')::numeric, (calc->>'rawChance')::numeric, v_odds, v_roll, v_caught, calc || jsonb_build_object('testOutcome', test_out, 'formId', form_id))
    ON CONFLICT (round_id, user_id) DO NOTHING;
    IF v_caught THEN
      INSERT INTO public.play_console_log (round_id, user_id, display_name, kind, item, message)
      SELECT r.id, rec.user_id, who, 'caught', species, '⭐ ' || who || ' caught ' || species || '!'
      WHERE NOT EXISTS (SELECT 1 FROM public.play_console_log l WHERE l.round_id = r.id AND l.user_id = rec.user_id AND l.kind = 'caught') ON CONFLICT DO NOTHING;
    ELSE
      INSERT INTO public.play_console_log (round_id, user_id, display_name, kind, item, message)
      SELECT r.id, rec.user_id, who, 'escaped', species, '✖ ' || who || ' was unable to catch ' || species || '. Better luck next encounter!'
      WHERE NOT EXISTS (SELECT 1 FROM public.play_console_log l WHERE l.round_id = r.id AND l.user_id = rec.user_id AND l.kind = 'escaped') ON CONFLICT DO NOTHING;
    END IF;
    IF v_caught AND NOT EXISTS (SELECT 1 FROM public.catches c WHERE c.round_id = rec.round_id AND c.user_id = rec.user_id) THEN
      v_level := coalesce(private.encounter_pokemon_level(r.dex, r.id), 5);
      v_mat := private.materialize_streamlink_catch(
        rec.user_id,
        form_id,
        v_level,
        'catch',
        'play:' || rec.round_id::text || ':' || rec.user_id::text,
        rec.ball,
        rec.round_id,
        private.variant_is_shiny(r.variant),
        'sl-ref-20261013-227b573',
        NULL,
        r.variant,
        species,
        r.gender
      );
      IF coalesce(v_mat->>'ok', 'false') IS DISTINCT FROM 'true' THEN
        IF coalesce((v_mat->>'replay')::boolean, false)
           OR coalesce(v_mat->'errors', '[]'::jsonb) ? 'already-settled' THEN
          IF NOT EXISTS (
            SELECT 1 FROM public.catches c
            WHERE c.round_id = rec.round_id AND c.user_id = rec.user_id
          ) THEN
            RAISE EXCEPTION 'wire-materialize-failed: already-settled-without-catch';
          END IF;
        ELSE
          RAISE EXCEPTION 'wire-materialize-failed: %', coalesce(v_mat->>'errors', v_mat::text);
        END IF;
      END IF;
      IF coalesce(v_mat->>'ok', 'false') = 'true' THEN
        BEGIN
          v_catch_id := NULL;
          v_life := NULL;
          IF nullif(btrim(v_mat->>'catchId'), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
            v_catch_id := (v_mat->>'catchId')::uuid;
          END IF;
          IF v_catch_id IS NOT NULL THEN
            SELECT a.lifecycle INTO v_life
            FROM private.species_mastery_activation AS a
            WHERE a.singleton
            FOR SHARE;
            IF v_life IN ('active', 'paused') THEN
              PERFORM private.note_species_mastery_catch(v_catch_id);
            END IF;
          END IF;
        EXCEPTION WHEN OTHERS THEN
          NULL;
        END;
      END IF;
    END IF;
  END LOOP;
  UPDATE public.encounter_rounds SET resolved = true, paused_at = null, last_action = coalesce(throw_line, last_action, 'Results locked in'), updated_at = now() WHERE id = r.id RETURNING * INTO r;
  RETURN r;
END;
$function$

CREATE OR REPLACE FUNCTION private.species_mastery_caught_at_freeze()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
BEGIN
  IF NEW.caught_at IS DISTINCT FROM OLD.caught_at THEN
    RAISE EXCEPTION 'capture timestamp is immutable' USING ERRCODE = '55000';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION private.stamp_catch_server_inserted_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
BEGIN
  NEW.server_inserted_at := clock_timestamp();
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION private.streamlink_complete_and_bind(p_prep jsonb, p_shiny boolean, p_nature_id integer, p_ability_pick bigint, p_iv_hp integer, p_iv_atk integer, p_iv_def integer, p_iv_spa integer, p_iv_spd integer, p_iv_spe integer, p_gender_roll bigint, p_specimen_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  v_build text;
  v_form_id int;
  ability_id int;
  ability_slot text;
  nature_id int := p_nature_id;
  nat private.ref_natures%ROWTYPE;
  gender text;
  moves jsonb;
  hp_max int;
  n_atk numeric := 1; n_def numeric := 1; n_spa numeric := 1; n_spd numeric := 1; n_spe numeric := 1;
  legacy text[];
  mon jsonb;
  ticket_uuid uuid;
  digest bytea;
  bind_st text;
  slots text[];
  pick int;
BEGIN
  IF p_specimen_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'errors', jsonb_build_array('missing-specimen-id'));
  END IF;
  IF p_prep IS NULL OR (p_prep->>'ok') IS DISTINCT FROM 'true' THEN
    RETURN coalesce(p_prep, jsonb_build_object('ok', false, 'errors', jsonb_build_array('bad-prep')));
  END IF;
  v_build := p_prep->>'build';
  v_form_id := private.streamlink_json_int(p_prep->'formId');
  SELECT coalesce(array_agg(x), ARRAY[]::text[])
    INTO slots
  FROM jsonb_array_elements_text(p_prep->'slots') x;
  IF slots IS NULL OR array_length(slots, 1) IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'errors', jsonb_build_array('no-legal-ability'));
  END IF;
  pick := ((p_ability_pick % array_length(slots, 1)) + array_length(slots, 1)) % array_length(slots, 1);
  ability_slot := slots[pick + 1];
  SELECT a.ability_id INTO ability_id
  FROM private.ref_form_abilities a
  WHERE a.content_build = v_build AND a.form_id = v_form_id AND a.slot = ability_slot;
  SELECT * INTO nat FROM private.ref_natures WHERE content_build = v_build AND id = nature_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'errors', jsonb_build_array('bad-nature'));
  END IF;
  gender := private.streamlink_gender(private.streamlink_json_int(p_prep->'genderRate'), p_gender_roll);
  moves := private.streamlink_level_up_slice(v_build, v_form_id, private.streamlink_json_int(p_prep->'level'));
  IF moves IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'errors', jsonb_build_array('unresolved-learnset'));
  END IF;
  IF nat.up_stat = 'atk' THEN n_atk := 1.1; ELSIF nat.down_stat = 'atk' THEN n_atk := 0.9; END IF;
  IF nat.up_stat = 'def' THEN n_def := 1.1; ELSIF nat.down_stat = 'def' THEN n_def := 0.9; END IF;
  IF nat.up_stat = 'spa' THEN n_spa := 1.1; ELSIF nat.down_stat = 'spa' THEN n_spa := 0.9; END IF;
  IF nat.up_stat = 'spd' THEN n_spd := 1.1; ELSIF nat.down_stat = 'spd' THEN n_spd := 0.9; END IF;
  IF nat.up_stat = 'spe' THEN n_spe := 1.1; ELSIF nat.down_stat = 'spe' THEN n_spe := 0.9; END IF;
  hp_max := private.streamlink_hp_max(
    private.streamlink_json_int(p_prep->'hp'), p_iv_hp, 0,
    private.streamlink_json_int(p_prep->'level')
  );
  SELECT coalesce(array_agg(x->>'name'), ARRAY[]::text[])
    INTO legacy
  FROM jsonb_array_elements(moves) x;

  mon := jsonb_build_object(
    'ok', true,
    'formId', v_form_id,
    'dex', private.streamlink_json_int(p_prep->'dex'),
    'level', private.streamlink_json_int(p_prep->'level'),
    'natureId', nature_id,
    'abilityId', ability_id,
    'abilitySlot', ability_slot,
    'ivs', jsonb_build_object('hp', p_iv_hp, 'atk', p_iv_atk, 'def', p_iv_def, 'spa', p_iv_spa, 'spd', p_iv_spd, 'spe', p_iv_spe),
    'evs', jsonb_build_object('hp', 0, 'atk', 0, 'def', 0, 'spa', 0, 'spd', 0, 'spe', 0),
    'moveSlots', moves,
    'legacyMoves', to_jsonb(legacy),
    'gender', gender,
    'shiny', coalesce(p_shiny, false),
    'friendship', private.streamlink_json_int(p_prep->'friendship'),
    'hpMax', hp_max,
    'hpCurrent', hp_max,
    'status', NULL,
    'heldItem', NULL,
    'gigantamaxFactor', false,
    'heightM', p_prep->'heightM',
    'weightKg', p_prep->'weightKg',
    'rulesetId', 'streamlink-gen9-xgen',
    'contentBuild', v_build,
    'hiddenGrant', false,
    'hiddenTicketId', NULL,
    'hiddenSpecimenId', NULL,
    'catchId', p_specimen_id,
    'stats', jsonb_build_object(
      'hp', hp_max,
      'atk', private.streamlink_stat(private.streamlink_json_int(p_prep->'atk'), p_iv_atk, 0, private.streamlink_json_int(p_prep->'level'), n_atk),
      'def', private.streamlink_stat(private.streamlink_json_int(p_prep->'def'), p_iv_def, 0, private.streamlink_json_int(p_prep->'level'), n_def),
      'spa', private.streamlink_stat(private.streamlink_json_int(p_prep->'spa'), p_iv_spa, 0, private.streamlink_json_int(p_prep->'level'), n_spa),
      'spd', private.streamlink_stat(private.streamlink_json_int(p_prep->'spd'), p_iv_spd, 0, private.streamlink_json_int(p_prep->'level'), n_spd),
      'spe', private.streamlink_stat(private.streamlink_json_int(p_prep->'spe'), p_iv_spe, 0, private.streamlink_json_int(p_prep->'level'), n_spe)
    ),
    'errors', '[]'::jsonb
  );

  IF coalesce((p_prep->>'hiddenPending')::boolean, false) THEN
    ticket_uuid := (p_prep->>'ticketUuid')::uuid;
    digest := private.streamlink_specimen_digest(mon);
    bind_st := private.streamlink_bind_hidden_ticket(ticket_uuid, p_specimen_id, digest);
    IF bind_st IS DISTINCT FROM 'ok' THEN
      IF bind_st = 'replay' THEN
        RETURN jsonb_build_object('ok', false, 'errors', jsonb_build_array('hidden-ticket-replay'));
      END IF;
      IF bind_st = 'expired' THEN
        RETURN jsonb_build_object('ok', false, 'errors', jsonb_build_array('hidden-ticket-expired'));
      END IF;
      RETURN jsonb_build_object('ok', false, 'errors', jsonb_build_array('hidden-not-authorized'));
    END IF;
    mon := mon || jsonb_build_object(
      'hiddenGrant', true,
      'hiddenTicketId', ticket_uuid,
      'hiddenSpecimenId', p_specimen_id
    );
  END IF;
  RETURN mon;
END
$function$

CREATE OR REPLACE FUNCTION private.streamlink_generate_prepare(p_form_id integer, p_level integer, p_ctx text, p_content_build text, p_hidden_ticket text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  build text := coalesce(p_content_build, 'sl-ref-20261013-227b573');
  form private.ref_forms%ROWTYPE;
  spec private.ref_species%ROWTYPE;
  errors text[] := ARRAY[]::text[];
  ticket_uuid uuid; ticket_st text; hidden_pending boolean := false; slots text[];
BEGIN
  IF p_ctx IS NULL OR p_ctx NOT IN ('generate', 'catch', 'grant', 'event', 'rebuild') THEN
    errors := array_append(errors, 'bad-ctx');
  END IF;
  IF p_level IS NULL OR p_level < 1 OR p_level > 100 THEN
    errors := array_append(errors, 'bad-level');
  END IF;
  SELECT * INTO form FROM private.ref_forms WHERE content_build = build AND form_id = p_form_id;
  IF NOT FOUND THEN errors := array_append(errors, 'unknown-form'); END IF;
  IF form.form_id IS NOT NULL THEN
    SELECT * INTO spec FROM private.ref_species WHERE content_build = build AND dex = form.dex;
    IF NOT FOUND THEN errors := array_append(errors, 'unknown-species'); END IF;
    IF form.learnset_status IS DISTINCT FROM 'resolved' OR form.learnset_version_group IS NULL THEN
      errors := array_append(errors, 'unresolved-learnset');
    END IF;
    IF private.streamlink_form_blocked(build, p_form_id) THEN errors := array_append(errors, 'g1-c1-blocked'); END IF;
    IF NOT private.streamlink_obtain_ok(build, coalesce(p_ctx, ''), p_form_id) THEN
      errors := array_append(errors, 'obtain-denied');
    END IF;
  END IF;
  IF p_hidden_ticket IS NOT NULL AND btrim(p_hidden_ticket) <> '' THEN
    BEGIN ticket_uuid := p_hidden_ticket::uuid;
    EXCEPTION WHEN others THEN errors := array_append(errors, 'hidden-ticket-invalid'); ticket_uuid := NULL;
    END;
  END IF;
  IF array_length(errors, 1) IS NOT NULL THEN
    RETURN jsonb_build_object('ok', false, 'errors', to_jsonb(errors));
  END IF;
  IF ticket_uuid IS NOT NULL THEN
    ticket_st := private.streamlink_lock_hidden_ticket(ticket_uuid, build, p_form_id, p_ctx);
    IF ticket_st = 'ok' THEN hidden_pending := true;
    ELSIF ticket_st = 'replay' THEN RETURN jsonb_build_object('ok', false, 'errors', jsonb_build_array('hidden-ticket-replay'));
    ELSIF ticket_st = 'expired' THEN RETURN jsonb_build_object('ok', false, 'errors', jsonb_build_array('hidden-ticket-expired'));
    ELSE RETURN jsonb_build_object('ok', false, 'errors', jsonb_build_array('hidden-not-authorized'));
    END IF;
  END IF;
  IF hidden_pending AND EXISTS (
    SELECT 1 FROM private.ref_form_abilities a
    WHERE a.content_build = build AND a.form_id = p_form_id AND a.slot = 'hidden'
  ) THEN
    slots := ARRAY['hidden']::text[];
  ELSE
    hidden_pending := false; ticket_uuid := NULL;
    SELECT coalesce(array_agg(a.slot ORDER BY a.slot), ARRAY[]::text[]) INTO slots
    FROM private.ref_form_abilities a
    WHERE a.content_build = build AND a.form_id = p_form_id AND a.slot IN ('1', '2');
  END IF;
  IF slots IS NULL OR array_length(slots, 1) IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'errors', jsonb_build_array('no-legal-ability'));
  END IF;
  RETURN jsonb_build_object(
    'ok', true, 'build', build, 'formId', form.form_id, 'dex', form.dex, 'level', p_level, 'ctx', p_ctx,
    'ticketUuid', ticket_uuid, 'hiddenPending', hidden_pending, 'slots', to_jsonb(slots),
    'genderRate', spec.gender_rate, 'friendship', spec.streamlink_base_friendship,
    'hp', form.hp, 'atk', form.atk, 'def', form.def, 'spa', form.spa, 'spd', form.spd, 'spe', form.spe,
    'heightM', form.height_m, 'weightKg', form.weight_kg
  );
END
$function$

CREATE OR REPLACE FUNCTION private.streamlink_json_int(p jsonb)
 RETURNS integer
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog'
AS $function$
BEGIN
  IF p IS NULL OR jsonb_typeof(p) IS DISTINCT FROM 'number' THEN
    RETURN NULL;
  END IF;
  IF (p #>> '{}') !~ '^-?[0-9]+$' THEN
    RETURN NULL;
  END IF;
  RETURN (p #>> '{}')::integer;
EXCEPTION WHEN others THEN
  RETURN NULL;
END
$function$

CREATE OR REPLACE FUNCTION private.streamlink_obtain_ok(p_content_build text, p_ctx text, p_form_id integer)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE o private.ref_obtain%ROWTYPE;
BEGIN
  SELECT * INTO o FROM private.ref_obtain WHERE content_build = p_content_build AND form_id = p_form_id;
  IF NOT FOUND THEN RETURN false; END IF;
  IF p_ctx IN ('evolve', 'trade', 'edit') THEN RETURN o.enabled; END IF;
  IF NOT o.enabled THEN RETURN false; END IF;
  IF p_ctx IN ('generate', 'catch', 'rebuild') THEN RETURN o.normal_encounter_enabled; END IF;
  IF p_ctx = 'grant' THEN RETURN o.admin_targetable; END IF;
  IF p_ctx = 'event' THEN RETURN o.event_targetable; END IF;
  RETURN false;
END
$function$

CREATE OR REPLACE FUNCTION private.streamlink_lock_hidden_ticket(p_ticket uuid, p_content_build text, p_form_id integer, p_ctx text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE v_red timestamptz; v_exp timestamptz; v_form integer; v_ctx text; v_build text;
BEGIN
  IF p_ticket IS NULL THEN RETURN 'missing'; END IF;
  SELECT t.redeemed_at, t.expires_at, t.form_id, t.ctx, t.content_build
    INTO v_red, v_exp, v_form, v_ctx, v_build
  FROM private.streamlink_hidden_tickets t WHERE t.ticket_id = p_ticket FOR UPDATE;
  IF NOT FOUND THEN RETURN 'unknown'; END IF;
  IF v_red IS NOT NULL THEN RETURN 'replay'; END IF;
  IF v_exp <= now() THEN RETURN 'expired'; END IF;
  IF v_build IS DISTINCT FROM p_content_build OR v_form IS DISTINCT FROM p_form_id OR v_ctx IS DISTINCT FROM p_ctx THEN
    RETURN 'mismatch';
  END IF;
  RETURN 'ok';
END
$function$

CREATE OR REPLACE FUNCTION private.round_phase(r encounter_rounds)
 RETURNS text
 LANGUAGE plpgsql
 STABLE
AS $function$
declare
  clk timestamptz;
begin
  if r is null or r.cancelled then
    return 'closed';
  end if;
  if not private.deadlines_complete(r.deadlines) then
    return coalesce(nullif(r.phase, ''), 'closed');
  end if;
  clk := coalesce(r.paused_at, now());
  return case
    when clk < (r.deadlines->>'join')::timestamptz then 'join'
    when clk < (r.deadlines->>'prepare')::timestamptz then 'prepare'
    when clk < (r.deadlines->>'throw')::timestamptz then 'throw'
    when clk < (r.deadlines->>'reveal')::timestamptz then 'reveal'
    else 'closed'
  end;
end;
$function$

CREATE OR REPLACE FUNCTION private.streamlink_bind_hidden_ticket(p_ticket uuid, p_specimen_id uuid, p_digest bytea)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE v_id uuid;
BEGIN
  IF p_ticket IS NULL OR p_specimen_id IS NULL OR p_digest IS NULL THEN RETURN 'missing'; END IF;
  UPDATE private.streamlink_hidden_tickets t
     SET redeemed_at = now(), specimen_id = p_specimen_id, specimen_digest = p_digest
   WHERE t.ticket_id = p_ticket AND t.redeemed_at IS NULL AND t.expires_at > now() AND t.specimen_digest IS NULL
  RETURNING t.ticket_id INTO v_id;
  IF v_id IS NOT NULL THEN RETURN 'ok'; END IF;
  IF EXISTS (SELECT 1 FROM private.streamlink_hidden_tickets t WHERE t.ticket_id = p_ticket AND t.redeemed_at IS NOT NULL) THEN RETURN 'replay'; END IF;
  IF EXISTS (SELECT 1 FROM private.streamlink_hidden_tickets t WHERE t.ticket_id = p_ticket AND t.expires_at <= now()) THEN RETURN 'expired'; END IF;
  RETURN 'mismatch';
END
$function$

CREATE OR REPLACE FUNCTION private.ensure_trainer_stats(p_uid uuid)
 RETURNS trainer_stats
 LANGUAGE plpgsql
AS $function$
declare
  row public.trainer_stats;
begin
  insert into public.trainer_stats (user_id) values (p_uid)
  on conflict (user_id) do nothing;
  select * into row from public.trainer_stats where user_id = p_uid;
  return row;
end;
$function$

CREATE OR REPLACE FUNCTION private.ensure_inventory(p_uid uuid)
 RETURNS inventories
 LANGUAGE plpgsql
AS $function$
declare inv public.inventories; inserted boolean := false;
begin
  insert into public.inventories (user_id) values (p_uid) on conflict (user_id) do nothing;
  get diagnostics inserted = row_count;
  if inserted then perform private.grant_starter_kit(p_uid); end if;
  perform private.flush_bits_pending(p_uid);
  select * into inv from public.inventories where user_id = p_uid;
  return inv;
end;
$function$

CREATE OR REPLACE FUNCTION private.materialize_streamlink_catch(p_user_id uuid, p_form_id integer, p_level integer, p_ctx text, p_source_key text, p_ball text DEFAULT 'poke'::text, p_round_id uuid DEFAULT NULL::uuid, p_shiny boolean DEFAULT false, p_content_build text DEFAULT 'sl-ref-20261013-227b573'::text, p_hidden_ticket text DEFAULT NULL::text, p_variant text DEFAULT 'normal'::text, p_name text DEFAULT NULL::text, p_gender text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  v_dex int;
  v_name text;
  inserted uuid;
  v_public text;
BEGIN
  IF private.streamlink_wire_is_enabled() THEN
    RETURN private.persist_streamlink_catch(
      p_user_id, p_form_id, p_level, p_ctx, p_source_key, p_ball, p_round_id,
      p_shiny, p_content_build, p_hidden_ticket, p_variant, p_name, p_gender
    );
  END IF;

  IF p_user_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'errors', jsonb_build_array('missing-user'), 'path', 'stamp');
  END IF;
  IF p_ctx IS NULL OR p_ctx NOT IN ('catch', 'grant', 'event') THEN
    RETURN jsonb_build_object('ok', false, 'errors', jsonb_build_array('bad-ctx'), 'path', 'stamp');
  END IF;
  IF p_source_key IS NULL OR btrim(p_source_key) = '' THEN
    RETURN jsonb_build_object('ok', false, 'errors', jsonb_build_array('missing-source-key'), 'path', 'stamp');
  END IF;
  IF p_ctx IN ('grant', 'event') AND private.streamlink_protected_trainer(p_user_id) THEN
    RETURN jsonb_build_object('ok', false, 'errors', jsonb_build_array('protected-trainer'), 'path', 'stamp');
  END IF;

  SELECT f.dex, initcap(replace(s.slug, '-', ' '))
    INTO v_dex, v_name
  FROM private.ref_forms f
  JOIN private.ref_species s
    ON s.content_build = f.content_build AND s.dex = f.dex
  WHERE f.content_build = coalesce(p_content_build, 'sl-ref-20261013-227b573')
    AND f.form_id = p_form_id;
  v_dex := coalesce(v_dex, p_form_id);
  v_name := coalesce(nullif(btrim(p_name), ''), v_name, 'Pokemon');

  BEGIN
    INSERT INTO public.catches (
      user_id, dex, name, variant, gender, ball, round_id, source_key, level, pokemon_form_id
    ) VALUES (
      p_user_id,
      v_dex,
      v_name,
      coalesce(nullif(btrim(p_variant), ''), 'normal'),
      coalesce(nullif(btrim(p_gender), ''), 'M'),
      coalesce(nullif(btrim(p_ball), ''), 'poke'),
      p_round_id,
      p_source_key,
      p_level,
      p_form_id
    )
    RETURNING id, public_id INTO inserted, v_public;
  EXCEPTION WHEN unique_violation THEN
    RETURN jsonb_build_object(
      'ok', false,
      'errors', jsonb_build_array('already-settled'),
      'replay', true,
      'path', 'stamp'
    );
  END;

  RETURN jsonb_build_object(
    'ok', true,
    'catchId', inserted,
    'publicId', v_public,
    'path', 'stamp'
  );
END
$function$

CREATE OR REPLACE FUNCTION private.stamp_catch_row(c catches)
 RETURNS catches
 LANGUAGE plpgsql
AS $function$
declare
  seed int;
  bounds int[];
  size_roll int;
  scale numeric;
  jitter numeric;
  trainer public.profiles%rowtype;
begin
  if c.public_id is null or btrim(c.public_id) = '' then
    c.public_id := 'LG' || lpad(nextval('public.catch_serial')::text, 8, '0');
  end if;
  seed := abs(('x' || substr(md5(c.id::text), 1, 8))::bit(32)::int);
  bounds := private.lgpe_level_bounds(c.dex);
  if c.level is null then
    if c.round_id is not null then
      c.level := private.encounter_pokemon_level(c.dex, c.round_id);
    else
      c.level := bounds[1] + (seed % (greatest(bounds[2] - bounds[1], 0) + 1));
    end if;
  end if;
  if c.iv_hp is null then c.iv_hp := (('x' || substr(md5(c.id::text || 'hp'), 1, 2))::bit(8)::int) % 32; end if;
  if c.iv_atk is null then c.iv_atk := (('x' || substr(md5(c.id::text || 'atk'), 1, 2))::bit(8)::int) % 32; end if;
  if c.iv_def is null then c.iv_def := (('x' || substr(md5(c.id::text || 'def'), 1, 2))::bit(8)::int) % 32; end if;
  if c.iv_spa is null then c.iv_spa := (('x' || substr(md5(c.id::text || 'spa'), 1, 2))::bit(8)::int) % 32; end if;
  if c.iv_spd is null then c.iv_spd := (('x' || substr(md5(c.id::text || 'spd'), 1, 2))::bit(8)::int) % 32; end if;
  if c.iv_spe is null then c.iv_spe := (('x' || substr(md5(c.id::text || 'spe'), 1, 2))::bit(8)::int) % 32; end if;
  if c.av_hp is null then c.av_hp := 0; end if;
  if c.av_atk is null then c.av_atk := 0; end if;
  if c.av_def is null then c.av_def := 0; end if;
  if c.av_spa is null then c.av_spa := 0; end if;
  if c.av_spd is null then c.av_spd := 0; end if;
  if c.av_spe is null then c.av_spe := 0; end if;
  if c.size_class is null or c.size_class not in ('XS','S','M','L','XL') then
    size_roll := seed % 256;
    c.size_class := case
      when size_roll < 12 then 'XS'
      when size_roll < 72 then 'S'
      when size_roll < 184 then 'M'
      when size_roll < 244 then 'L'
      else 'XL'
    end;
  end if;
  if c.moves is null or cardinality(c.moves) = 0 then
    c.moves := private.lgpe_pick_moves(c.dex, c.level);
  end if;
  c.gender := private.lgpe_roll_gender(c.dex, seed, c.gender);
  if c.met_level is null then
    c.met_level := c.level;
  end if;
  if c.met_location is null or btrim(c.met_location) = '' then
    c.met_location := private.lgpe_habitat(c.dex);
  end if;
  if c.friendship is null then
    c.friendship := 0;
  end if;
  scale := case c.size_class
    when 'XS' then 0.81
    when 'S' then 0.91
    when 'L' then 1.09
    when 'XL' then 1.21
    else 1.0
  end;
  jitter := 0.97 + ((seed / 23) % 7) * 0.01;
  if c.height_m is null then
    c.height_m := round((0.4 + (c.dex % 17) * 0.08) * scale * jitter, 2);
  end if;
  if c.weight_kg is null then
    c.weight_kg := round((5.0 + (c.dex % 29) * 1.7) * scale * jitter, 1);
  end if;
  if c.ot_user_id is null then
    c.ot_user_id := c.user_id;
  end if;
  if c.ot_name is null or btrim(c.ot_name) = '' or c.ot_number is null then
    select * into trainer from public.profiles where id = coalesce(c.ot_user_id, c.user_id);
    if c.ot_name is null or btrim(c.ot_name) = '' then
      c.ot_name := coalesce(nullif(btrim(trainer.display_name), ''), nullif(trainer.twitch_login, ''), 'Trainer');
    end if;
    if c.ot_number is null and trainer.id is not null then
      c.ot_number := 10000 + (abs(hashtext(trainer.id::text)) % 90000);
    end if;
  end if;
  return c;
end;
$function$

CREATE OR REPLACE FUNCTION private.enqueue_species_mastery_event(p_catch_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
DECLARE
  lifecycle text;
BEGIN
  IF p_catch_id IS NULL THEN
    RAISE EXCEPTION 'mastery outbox rejected: missing specimen' USING ERRCODE = '23514';
  END IF;
  PERFORM 1 FROM public.catches WHERE id = p_catch_id FOR SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'mastery outbox rejected: specimen is not on file' USING ERRCODE = '23514';
  END IF;
  SELECT a.lifecycle INTO lifecycle
  FROM private.species_mastery_activation AS a
  WHERE a.singleton
  FOR SHARE;
  IF lifecycle IS DISTINCT FROM 'active' AND lifecycle IS DISTINCT FROM 'paused' THEN
    RAISE EXCEPTION 'mastery outbox rejected: recording is not open' USING ERRCODE = '23514';
  END IF;
  INSERT INTO private.species_mastery_outbox (catch_id)
  VALUES (p_catch_id)
  ON CONFLICT (catch_id) DO NOTHING;
  RETURN p_catch_id;
END;
$function$

CREATE OR REPLACE FUNCTION private.announce_throws(p_round uuid)
 RETURNS text
 LANGUAGE plpgsql
AS $function$
DECLARE
  rec public.encounter_players%ROWTYPE;
  who text;
  line text;
  last_line text;
BEGIN
  FOR rec IN
    SELECT ep.*
    FROM public.encounter_players ep
    WHERE ep.round_id = p_round
      AND ep.ball IS NOT NULL
      AND ep.throw_processed = false
    ORDER BY coalesce(private.trainer_label(ep.user_id), 'Trainer'), ep.user_id
    FOR UPDATE
  LOOP
    who := coalesce(private.trainer_label(rec.user_id), 'A trainer');
    IF rec.result_reason IS DISTINCT FROM 'standard_throw' THEN
      BEGIN
        PERFORM private.spend_bag_item(rec.user_id, rec.ball);
      EXCEPTION
        WHEN SQLSTATE 'NB001' THEN
          UPDATE public.encounter_players ep
            SET throw_processed = true, result_reason = 'no_ball_left'
            WHERE ep.round_id = rec.round_id AND ep.user_id = rec.user_id;
          INSERT INTO public.play_console_log (round_id, user_id, display_name, kind, item, message)
          SELECT p_round, rec.user_id, who, 'timeout', rec.ball,
                 '⌛ ' || who || ' ran out of ' || private.item_label(rec.ball) || 's before the throw.'
          WHERE NOT EXISTS (
            SELECT 1 FROM public.play_console_log l
            WHERE l.round_id = p_round AND l.user_id = rec.user_id AND l.kind = 'timeout'
          )
          ON CONFLICT DO NOTHING;
          CONTINUE;
      END;
    END IF;
    UPDATE public.encounter_players ep
      SET throw_processed = true
      WHERE ep.round_id = rec.round_id AND ep.user_id = rec.user_id;
    line := who || ' has thrown ' || private.a_or_an(private.item_label(rec.ball)) || '!';
    PERFORM private.log_activity(p_round, rec.user_id, 'threw', rec.ball);
    UPDATE public.play_console_log l
      SET message = line
      WHERE l.round_id = p_round
        AND l.user_id = rec.user_id
        AND l.kind = 'threw'
        AND coalesce(l.message, '') = '';
    last_line := line;
  END LOOP;

  FOR rec IN
    SELECT ep.*
    FROM public.encounter_players ep
    WHERE ep.round_id = p_round AND ep.ball IS NULL AND ep.result IS NULL
  LOOP
    who := coalesce(private.trainer_label(rec.user_id), 'A trainer');
    INSERT INTO public.play_console_log (round_id, user_id, display_name, kind, item, message)
    SELECT p_round, rec.user_id, who, 'timeout', NULL,
           '⌛ ' || who || ' did not choose a Poké Ball in time.'
    WHERE NOT EXISTS (
      SELECT 1 FROM public.play_console_log l
      WHERE l.round_id = p_round AND l.user_id = rec.user_id AND l.kind = 'timeout'
    )
    ON CONFLICT DO NOTHING;
  END LOOP;

  RETURN last_line;
END;
$function$

CREATE OR REPLACE FUNCTION private.capture_chance(p_dex integer, p_ball text, p_berry text DEFAULT NULL::text, p_honey_contributors integer DEFAULT 0, p_honey_participants integer DEFAULT 0, p_contributed_honey boolean DEFAULT false, p_owns_species boolean DEFAULT false, p_is_shiny boolean DEFAULT false, p_other_multiplier numeric DEFAULT 1.0, p_at timestamp with time zone DEFAULT now(), p_config jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
declare
  cfg jsonb := coalesce(p_config, private.capture_config());
  s public.species%rowtype;
  base numeric;
  ball jsonb;
  berry jsonb;
  honey jsonb;
  contributor numeric;
  shiny numeric;
  event numeric;
  other numeric := coalesce(p_other_multiplier, 1.0);
  raw numeric;
  final numeric;
  min_chance numeric := coalesce((cfg->>'minChance')::numeric, 0.02);
  max_chance numeric := coalesce((cfg->>'maxChance')::numeric, 0.85);
begin
  select * into s from public.species where dex = p_dex;
  base := private.capture_base_chance(s.catch_rate, cfg);
  ball := private.capture_ball_modifier(p_ball, p_dex, p_owns_species, p_at, cfg);
  berry := private.capture_berry_modifier(p_berry);
  honey := private.capture_honey_modifier(p_honey_contributors, p_honey_participants, cfg);
  contributor := case
    when coalesce(p_contributed_honey, false) then coalesce((cfg->>'honeyContributorBonus')::numeric, 1.0)
    else 1.0
  end;
  shiny := case when coalesce(p_is_shiny, false)
    then coalesce((cfg->>'shinyMultiplier')::numeric, 1.0) else 1.0 end;
  event := coalesce((cfg->>'eventMultiplier')::numeric, 1.0);

  raw := base
       * (ball->>'multiplier')::numeric
       * (berry->>'multiplier')::numeric
       * (honey->>'multiplier')::numeric
       * contributor
       * shiny
       * event
       * other;

  if coalesce((ball->>'guaranteed')::boolean, false) then
    final := 1.0;
  else
    final := least(max_chance, greatest(min_chance, raw));
  end if;

  return jsonb_build_object(
    'dex', p_dex,
    'species', s.name,
    'catchRate', s.catch_rate,
    'baseChance', base,
    'ball', ball,
    'berry', berry,
    'honey', honey,
    'honeyContributorMultiplier', contributor,
    'shinyMultiplier', shiny,
    'eventMultiplier', event,
    'otherMultiplier', other,
    'rawChance', raw,
    'finalChance', final,
    'guaranteed', coalesce((ball->>'guaranteed')::boolean, false),
    'minChance', min_chance,
    'maxChance', max_chance
  );
end;
$function$

CREATE OR REPLACE FUNCTION private.grant_xp(p_uid uuid, p_amount integer, p_type text, p_reason text DEFAULT NULL::text, p_meta jsonb DEFAULT '{}'::jsonb)
 RETURNS integer
 LANGUAGE plpgsql
AS $function$
declare
  before_xp int;
  after_xp int;
  before_lvl int;
  after_lvl int;
  idem text := nullif(p_meta->>'idempotency', '');
  prior int;
begin
  if p_uid is null or coalesce(p_amount, 0) = 0 then
    select xp into before_xp from public.profiles where id = p_uid;
    return coalesce(before_xp, 0);
  end if;
  if idem is not null then
    select xp_after into prior from public.xp_ledger where user_id = p_uid and idempotency = idem;
    if found then
      return prior;
    end if;
  end if;
  select xp into before_xp from public.profiles where id = p_uid for update;
  if not found then
    return 0;
  end if;
  before_lvl := private.trainer_level(before_xp);
  after_xp := greatest(0, before_xp + p_amount);
  update public.profiles
     set xp = after_xp, last_seen_at = now(), updated_at = now()
   where id = p_uid;
  insert into public.xp_ledger (user_id, amount, type, reason, idempotency, related_round, xp_before, xp_after)
  values (
    p_uid, p_amount, coalesce(p_type, 'XP'), p_reason, idem,
    nullif(p_meta->>'relatedRound', '')::uuid, before_xp, after_xp
  );
  after_lvl := private.trainer_level(after_xp);
  if after_lvl > before_lvl then
    perform private.process_level_ups(p_uid, before_lvl, after_lvl, true);
  end if;
  return after_xp;
end;
$function$

CREATE OR REPLACE FUNCTION private.register_capture_collection(p_catch catches)
 RETURNS void
 LANGUAGE plpgsql
AS $function$
declare
  spec public.species;
  pay int;
  first_species boolean;
  fam int;
begin
  if private.round_is_test(p_catch.round_id) then return; end if;
  select * into spec from public.species where dex = p_catch.dex;
  fam := coalesce(spec.family_id, p_catch.dex);
  if private.family_has_enabled_evo(fam) then
    pay := private.candy_for_stage(spec.evo_stage);
    perform private.grant_family_candy(p_catch.user_id, fam, pay, 'CATCH_REWARD', 'Catch reward', jsonb_build_object('idempotency', 'candy-catch:' || p_catch.id::text, 'catchId', p_catch.id::text));
  end if;
  perform private.grant_mastery(p_catch.user_id, p_catch.dex, 1, 'CATCH', 'mastery-catch:' || p_catch.id::text);
  if p_catch.variant like '%shiny%' then
    perform private.grant_mastery(p_catch.user_id, p_catch.dex, 3, 'SHINY', 'mastery-shiny:' || p_catch.id::text);
  end if;
  if p_catch.gender = 'Female' and p_catch.dex = any (private.female_visual_dex()) then
    select not exists (select 1 from public.catches where user_id = p_catch.user_id and dex = p_catch.dex and id <> p_catch.id and (gender = 'Female' or variant like '%female%')) into first_species;
    if first_species then
      perform private.grant_mastery(p_catch.user_id, p_catch.dex, 1, 'VARIANT', 'mastery-female:' || p_catch.id::text);
    end if;
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION private.capture_throw_context(p_round encounter_rounds, p_uid uuid, p_ball_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
declare
  prepare_at timestamptz;
  throw_at timestamptz;
  used timestamptz := coalesce(p_ball_at, now());
  progress numeric := 0.5;
  lvl int := 1;
  g text := '';
begin
  if p_round.deadlines is not null then
    prepare_at := (p_round.deadlines->>'prepare')::timestamptz;
    throw_at := coalesce((p_round.deadlines->>'throw')::timestamptz, (p_round.deadlines->>'reveal')::timestamptz);
    if prepare_at is not null and throw_at is not null and throw_at > prepare_at then
      progress := extract(epoch from (used - prepare_at)) / extract(epoch from (throw_at - prepare_at));
    end if;
  end if;
  select private.trainer_level(xp) into lvl from public.profiles where id = p_uid;
  g := coalesce(p_round.gender, '');
  return jsonb_build_object('throwProgress', progress, 'trainerLevel', coalesce(lvl, 1), 'gender', g);
end;
$function$

CREATE OR REPLACE FUNCTION private.canonical_form_id(p_dex integer, p_form_id integer)
 RETURNS integer
 LANGUAGE plpgsql
 STABLE
AS $function$
declare
  f public.pokemon_forms;
begin
  if p_dex is null or p_dex < 1 then
    raise exception 'Invalid species.';
  end if;
  if p_form_id is null or p_form_id = p_dex then
    if not exists (select 1 from public.pokemon_forms where pokemon_form_id = p_dex and is_base) then
      -- Base row missing: still treat NationalDex as base identity.
      return p_dex;
    end if;
    return p_dex;
  end if;
  select * into f from public.pokemon_forms where pokemon_form_id = p_form_id;
  if f.pokemon_form_id is null then
    raise exception 'Unknown form id %.', p_form_id;
  end if;
  if f.dex is distinct from p_dex then
    raise exception 'Form % does not belong to species %.', p_form_id, p_dex;
  end if;
  return f.pokemon_form_id;
end;
$function$

CREATE OR REPLACE FUNCTION private.form_display_name(p_dex integer, p_form_id integer)
 RETURNS text
 LANGUAGE plpgsql
 STABLE
AS $function$
declare
  f public.pokemon_forms;
  species_name text;
  fid int;
begin
  select name into species_name from public.species where dex = p_dex;
  species_name := coalesce(species_name, 'Pokémon');
  fid := private.canonical_form_id(p_dex, p_form_id);
  select * into f from public.pokemon_forms where pokemon_form_id = fid;
  if f.pokemon_form_id is null or f.is_base then
    return species_name;
  end if;
  return species_name || ' — ' || f.form_label;
end;
$function$

CREATE OR REPLACE FUNCTION private.mark_seen(p_uid uuid, p_dex integer, p_form_id integer DEFAULT NULL::integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  fid integer;
  form_dex integer;
begin
  if p_uid is null or p_dex is null or p_dex < 1 or p_dex > 151 then
    return;
  end if;

  insert into public.species_seen (user_id, dex)
  values (p_uid, p_dex)
  on conflict (user_id, dex) do nothing;

  fid := nullif(p_form_id, 0);
  if fid is null then
    fid := p_dex;
  end if;

  select pf.dex into form_dex
    from public.pokemon_forms pf
   where pf.pokemon_form_id = fid;

  if form_dex is null then
    fid := p_dex;
  elsif form_dex <> p_dex then
    return;
  end if;

  insert into public.form_seen (user_id, form_id, dex)
  values (p_uid, fid, p_dex)
  on conflict (user_id, form_id) do nothing;
end;
$function$

CREATE OR REPLACE FUNCTION private.grant_starter_kit(p_uid uuid)
 RETURNS void
 LANGUAGE plpgsql
AS $function$
declare kit jsonb := private.economy_config()->'starterKit';
begin
  update public.inventories set starter_granted = true where user_id = p_uid and starter_granted = false;
  if not found then return; end if;
  perform private.grant_known(p_uid, jsonb_build_object('pokeball', coalesce((kit->>'pokeball')::int,10), 'berry', coalesce((kit->>'berry')::int,3), 'greatball', coalesce((kit->>'greatball')::int,1)));
  perform private.adjust_coins(p_uid, coalesce((kit->>'coins')::int,250), 'STARTER_KIT', 'Welcome kit', jsonb_build_object('idempotency', 'starter:' || p_uid::text));
end;
$function$

CREATE OR REPLACE FUNCTION private.streamlink_sha256(p_text text)
 RETURNS bytea
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog'
AS $function$
BEGIN
  IF to_regprocedure('extensions.digest(bytea, text)') IS NOT NULL THEN
    RETURN extensions.digest(convert_to(p_text, 'UTF8'), 'sha256');
  END IF;
  IF to_regprocedure('public.digest(bytea, text)') IS NOT NULL THEN
    RETURN public.digest(convert_to(p_text, 'UTF8'), 'sha256');
  END IF;
  RAISE EXCEPTION 'pgcrypto digest(sha256) is required';
END
$function$

CREATE OR REPLACE FUNCTION private.trainer_level(p_xp integer)
 RETURNS integer
 LANGUAGE plpgsql
 STABLE
AS $function$
declare
  cap int := greatest(1, least(coalesce((private.progression_config()->>'maxLevel')::int, 100), 200));
  xp int := greatest(coalesce(p_xp, 0), 0);
  lvl int := 1;
begin
  while lvl < cap and xp >= private.xp_to_reach_level(lvl + 1) loop
    lvl := lvl + 1;
  end loop;
  return lvl;
end;
$function$

CREATE OR REPLACE FUNCTION private.persist_streamlink_catch(p_user_id uuid, p_form_id integer, p_level integer, p_ctx text, p_source_key text, p_ball text DEFAULT 'poke'::text, p_round_id uuid DEFAULT NULL::uuid, p_shiny boolean DEFAULT false, p_content_build text DEFAULT 'sl-ref-20261013-227b573'::text, p_hidden_ticket text DEFAULT NULL::text, p_variant text DEFAULT 'normal'::text, p_name text DEFAULT NULL::text, p_gender text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  catch_id uuid;
  prep jsonb;
  mon jsonb;
  legal jsonb;
  ticket_uuid uuid;
  v_name text;
  v_variant text;
  v_public text;
  legacy text[];
  inserted uuid;
BEGIN
  IF NOT private.streamlink_wire_is_enabled() THEN
    RETURN jsonb_build_object('ok', false, 'errors', jsonb_build_array('wire-disabled'), 'path', 'stamp');
  END IF;
  IF p_user_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'errors', jsonb_build_array('missing-user'));
  END IF;
  IF p_ctx IS NULL OR p_ctx NOT IN ('catch', 'grant', 'event') THEN
    RETURN jsonb_build_object('ok', false, 'errors', jsonb_build_array('bad-ctx'));
  END IF;
  IF p_source_key IS NULL OR btrim(p_source_key) = '' THEN
    RETURN jsonb_build_object('ok', false, 'errors', jsonb_build_array('missing-source-key'));
  END IF;
  IF p_ctx = 'catch' AND p_source_key NOT LIKE 'play:%' THEN
    RETURN jsonb_build_object('ok', false, 'errors', jsonb_build_array('bad-source-key'));
  END IF;
  IF p_ctx = 'grant' AND p_source_key NOT LIKE 'grant:%' THEN
    RETURN jsonb_build_object('ok', false, 'errors', jsonb_build_array('bad-source-key'));
  END IF;
  IF p_ctx = 'event' AND p_source_key NOT LIKE 'event:%' THEN
    RETURN jsonb_build_object('ok', false, 'errors', jsonb_build_array('bad-source-key'));
  END IF;
  IF p_ctx IN ('grant', 'event') AND private.streamlink_protected_trainer(p_user_id) THEN
    RETURN jsonb_build_object('ok', false, 'errors', jsonb_build_array('protected-trainer'));
  END IF;

  catch_id := gen_random_uuid();
  prep := private.streamlink_generate_prepare(
    p_form_id, p_level, p_ctx, coalesce(p_content_build, 'sl-ref-20261013-227b573'), p_hidden_ticket
  );
  IF (prep->>'ok') IS DISTINCT FROM 'true' THEN
    RETURN prep;
  END IF;

  mon := private.streamlink_complete_and_bind(
    prep,
    coalesce(p_shiny, false),
    (private.streamlink_secure_u32() % 25)::int + 1,
    (private.streamlink_secure_u32() % 2147483647)::int,
    (private.streamlink_secure_u32() % 32)::int,
    (private.streamlink_secure_u32() % 32)::int,
    (private.streamlink_secure_u32() % 32)::int,
    (private.streamlink_secure_u32() % 32)::int,
    (private.streamlink_secure_u32() % 32)::int,
    (private.streamlink_secure_u32() % 32)::int,
    private.streamlink_secure_u32(),
    catch_id
  );
  IF (mon->>'ok') IS DISTINCT FROM 'true' THEN
    RETURN mon;
  END IF;

  IF (prep->>'ticketUuid') IS NOT NULL AND btrim(prep->>'ticketUuid') <> '' THEN
    ticket_uuid := (prep->>'ticketUuid')::uuid;
  END IF;
  legal := private.assert_streamlink_legal(mon, p_ctx, ticket_uuid);
  IF (legal->>'ok') IS DISTINCT FROM 'true' THEN
    RETURN legal;
  END IF;

  SELECT initcap(replace(s.slug, '-', ' '))
    INTO v_name
  FROM private.ref_species s
  WHERE s.content_build = prep->>'build'
    AND s.dex = private.streamlink_json_int(prep->'dex');
  v_name := coalesce(nullif(btrim(p_name), ''), v_name, 'Pokemon');
  v_variant := CASE
    WHEN coalesce(p_shiny, false) THEN 'shiny'
    ELSE coalesce(nullif(btrim(p_variant), ''), 'normal')
  END;
  v_public := private.streamlink_next_public_id('SL');
  SELECT coalesce(array_agg(x), ARRAY[]::text[])
    INTO legacy
  FROM jsonb_array_elements_text(mon->'legacyMoves') x;

  BEGIN
    INSERT INTO public.catches (
      id, user_id, dex, name, variant, gender, ball, round_id, source_key,
      public_id, level, pokemon_form_id,
      iv_hp, iv_atk, iv_def, iv_spa, iv_spd, iv_spe,
      av_hp, av_atk, av_def, av_spa, av_spd, av_spe,
      moves, friendship, height_m, weight_kg,
      nature_id, ability_id, ability_slot,
      ev_hp, ev_atk, ev_def, ev_spa, ev_spd, ev_spe,
      move_slots, ruleset_id, content_build,
      hp_current, hp_max, status, held_item, gigantamax_factor
    ) VALUES (
      catch_id,
      p_user_id,
      private.streamlink_json_int(mon->'dex'),
      v_name,
      v_variant,
      coalesce(nullif(btrim(p_gender), ''), mon->>'gender'),
      coalesce(nullif(btrim(p_ball), ''), 'poke'),
      p_round_id,
      p_source_key,
      v_public,
      private.streamlink_json_int(mon->'level'),
      private.streamlink_json_int(mon->'formId'),
      private.streamlink_json_int(mon#>'{ivs,hp}'),
      private.streamlink_json_int(mon#>'{ivs,atk}'),
      private.streamlink_json_int(mon#>'{ivs,def}'),
      private.streamlink_json_int(mon#>'{ivs,spa}'),
      private.streamlink_json_int(mon#>'{ivs,spd}'),
      private.streamlink_json_int(mon#>'{ivs,spe}'),
      0, 0, 0, 0, 0, 0,
      legacy,
      private.streamlink_json_int(mon->'friendship'),
      (mon->>'heightM')::numeric,
      (mon->>'weightKg')::numeric,
      private.streamlink_json_int(mon->'natureId'),
      private.streamlink_json_int(mon->'abilityId'),
      mon->>'abilitySlot',
      0, 0, 0, 0, 0, 0,
      mon->'moveSlots',
      mon->>'rulesetId',
      mon->>'contentBuild',
      private.streamlink_json_int(mon->'hpCurrent'),
      private.streamlink_json_int(mon->'hpMax'),
      NULL,
      NULL,
      false
    )
    RETURNING id INTO inserted;
  EXCEPTION WHEN unique_violation THEN
    RETURN jsonb_build_object(
      'ok', false,
      'errors', jsonb_build_array('already-settled'),
      'replay', true,
      'path', 'wire'
    );
  END;

  RETURN jsonb_build_object(
    'ok', true,
    'catchId', inserted,
    'publicId', v_public,
    'path', 'wire',
    'mon', mon
  );
END
$function$

CREATE OR REPLACE FUNCTION private.lgpe_pick_moves(p_dex integer, p_level integer)
 RETURNS text[]
 LANGUAGE plpgsql
 STABLE
AS $function$
declare
  picked text[];
begin
  select coalesce(array_agg(x.n order by x.ord), '{}'::text[])
    into picked
    from (
      select m->>'n' as n, row_number() over (order by coalesce((m->>'l')::int, 0) desc, m->>'n') as ord
      from public.lgpe_species s
      cross join lateral jsonb_array_elements(s.moves) m
      where s.dex = p_dex
        and coalesce(m->>'m', 'level-up') = 'level-up'
        and coalesce((m->>'l')::int, 0) <= greatest(coalesce(p_level, 1), 1)
      limit 4
    ) x;
  if coalesce(cardinality(picked), 0) = 0 then
    select coalesce(array_agg(x.n order by x.ord), '{}'::text[])
      into picked
      from (
        select m->>'n' as n, row_number() over (order by coalesce((m->>'l')::int, 0), m->>'n') as ord
        from public.lgpe_species s
        cross join lateral jsonb_array_elements(s.moves) m
        where s.dex = p_dex
        limit 4
      ) x;
  end if;
  if coalesce(cardinality(picked), 0) = 0 then
    picked := array['Tackle'];
  end if;
  return picked;
end;
$function$

CREATE OR REPLACE FUNCTION private.flush_bits_pending(p_uid uuid)
 RETURNS void
 LANGUAGE plpgsql
AS $function$
declare rec record; item jsonb; logins text[]; idents text[];
begin
  if p_uid is null then return; end if;
  if current_setting('play.flushing_bits', true) = '1' then return; end if;
  perform set_config('play.flushing_bits', '1', true);
  select array_agg(distinct lower(x.login)) into logins from (
    select c.twitch_login as login from public.twitch_connections c where c.user_id = p_uid and c.confirmed and c.gameplay_enabled
    union select p.twitch_login from public.profiles p where p.id = p_uid and p.twitch_login is not null
  ) x where btrim(coalesce(x.login, '')) <> '';
  select array_agg(distinct x.id) into idents from (
    select c.twitch_user_id as id from public.twitch_connections c where c.user_id = p_uid and c.confirmed and c.gameplay_enabled
    union select p.twitch_user_id from public.profiles p where p.id = p_uid and p.twitch_user_id is not null
  ) x where btrim(coalesce(x.id, '')) <> '';
  if logins is null and idents is null then return; end if;
  for rec in
    select event_id, sku, twitch_login, twitch_user_id, bits, title from private.bits_pending
     where (logins is not null and lower(twitch_login) = any (logins))
        or (idents is not null and twitch_user_id = any (idents))
     order by created_at
  loop
    if exists (select 1 from public.twitch_connections c where c.user_id = p_uid and c.confirmed and (lower(c.twitch_login) = lower(rec.twitch_login) or (rec.twitch_user_id is not null and c.twitch_user_id = rec.twitch_user_id)) and not c.gameplay_enabled) then
      delete from private.bits_pending where event_id = rec.event_id;
      update private.bits_events set detail = 'Skipped. That Twitch identity is excluded from gameplay rewards.', granted = false, status = 'skipped_bot', trainer_id = p_uid where event_id = rec.event_id;
      continue;
    end if;
    select elem into item from jsonb_array_elements(private.store_catalog()->'bits') as elem where elem->>'sku' = rec.sku;
    if item is null then
      delete from private.bits_pending where event_id = rec.event_id;
      update private.bits_events set detail = 'Unknown Bits pack.', granted = false, status = 'failed' where event_id = rec.event_id;
      continue;
    end if;
    begin
      perform private.grant_items(p_uid, item->'grants', 'BITS_REWARD', rec.sku, 'bits:' || rec.event_id, true);
      insert into public.trainer_notices (user_id, kind, title, body, payload)
      values (p_uid, 'support', 'THANK YOU! ★', (item->>'name') || ' added to your bag.', jsonb_build_object('type', 'support', 'sku', rec.sku, 'name', item->>'name', 'bits', rec.bits, 'grants', item->'grants', 'eventId', rec.event_id));
      insert into private.bits_support_totals (user_id, bits_total, updated_at) values (p_uid, greatest(coalesce(rec.bits, 0), 0), now())
      on conflict (user_id) do update set bits_total = private.bits_support_totals.bits_total + excluded.bits_total, updated_at = now();
      delete from private.bits_pending where event_id = rec.event_id;
      update private.bits_events set granted = true, status = 'fulfilled', trainer_id = p_uid, detail = 'Granted ' || (item->>'name') || '.', pack_name = item->>'name', grants = coalesce(item->'grants', '{}'::jsonb) where event_id = rec.event_id;
    exception when others then
      update private.bits_events set status = 'failed', detail = sqlerrm, trainer_id = p_uid where event_id = rec.event_id;
    end;
  end loop;
end;$function$

CREATE OR REPLACE FUNCTION private.spend_bag_item(p_uid uuid, p_item text)
 RETURNS void
 LANGUAGE plpgsql
AS $function$
DECLARE
  spent int;
BEGIN
  IF p_item = 'berry' THEN
    UPDATE public.inventories SET berry = berry - 1, updated_at = now()
      WHERE user_id = p_uid AND berry > 0;
  ELSIF p_item = 'bait' THEN
    UPDATE public.inventories SET bait = bait - 1, updated_at = now()
      WHERE user_id = p_uid AND bait > 0;
  ELSIF p_item = 'pokeball' THEN
    UPDATE public.inventories SET pokeball = pokeball - 1, updated_at = now()
      WHERE user_id = p_uid AND pokeball > 0;
  ELSIF p_item = 'greatball' THEN
    UPDATE public.inventories SET greatball = greatball - 1, updated_at = now()
      WHERE user_id = p_uid AND greatball > 0;
  ELSIF p_item = 'ultraball' THEN
    UPDATE public.inventories SET ultraball = ultraball - 1, updated_at = now()
      WHERE user_id = p_uid AND ultraball > 0;
  ELSIF private.is_capture_berry(p_item) THEN
    UPDATE public.inventories
      SET berries = jsonb_set(
            coalesce(berries, '{}'::jsonb),
            ARRAY[p_item],
            to_jsonb(coalesce((berries->>p_item)::int, 0) - 1)
          ),
          updated_at = now()
      WHERE user_id = p_uid
        AND coalesce((berries->>p_item)::int, 0) > 0;
  ELSIF p_item = ANY (private.extra_ball_keys()) THEN
    UPDATE public.inventories
      SET balls = jsonb_set(
            coalesce(balls, '{}'::jsonb),
            ARRAY[p_item],
            to_jsonb(coalesce((balls->>p_item)::int, 0) - 1)
          ),
          updated_at = now()
      WHERE user_id = p_uid
        AND coalesce((balls->>p_item)::int, 0) > 0;
  ELSE
    RAISE EXCEPTION 'Unknown item.';
  END IF;
  GET DIAGNOSTICS spent = ROW_COUNT;
  IF spent = 0 THEN
    RAISE EXCEPTION 'You have no % left. No item spent.', private.item_label(p_item)
      USING ERRCODE = 'NB001';
  END IF;
  INSERT INTO public.item_ledger (user_id, item_key, amount, reason, source_id, idempotency)
  VALUES (
    p_uid, p_item, -1, 'BAG_SPEND', NULL,
    'bag-spend:' || p_uid::text || ':' || p_item || ':' || gen_random_uuid()::text
  );
END;
$function$

CREATE OR REPLACE FUNCTION private.lgpe_roll_gender(p_dex integer, p_seed integer, p_current text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
declare
  rate int := private.lgpe_gender_rate(p_dex);
  cur text := coalesce(p_current, '');
begin
  if rate = -1 then
    return 'Genderless';
  end if;
  if rate = 0 then
    return 'Male';
  end if;
  if rate = 8 then
    return 'Female';
  end if;
  if cur in ('Male', 'Female') then
    return cur;
  end if;
  if (abs(p_seed) % 8) < rate then
    return 'Female';
  end if;
  return 'Male';
end;
$function$

CREATE OR REPLACE FUNCTION private.grant_family_candy(p_uid uuid, p_family integer, p_amount integer, p_type text, p_reason text, p_meta jsonb DEFAULT '{}'::jsonb)
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  idem text := nullif(p_meta->>'idempotency', '');
  before_qty int := 0;
  after_qty int;
begin
  if p_uid is null or p_family is null or coalesce(p_amount, 0) = 0 then
    return coalesce((select qty from public.family_candy where user_id = p_uid and family_id = p_family), 0);
  end if;
  if idem is not null and exists (
    select 1 from public.candy_ledger where user_id = p_uid and idempotency = idem
  ) then
    return (select qty_after from public.candy_ledger where user_id = p_uid and idempotency = idem);
  end if;
  insert into public.family_candy (user_id, family_id, qty)
  values (p_uid, p_family, 0)
  on conflict do nothing;
  select qty into before_qty from public.family_candy where user_id = p_uid and family_id = p_family for update;
  after_qty := before_qty + p_amount;
  if after_qty < 0 then
    raise exception 'Not enough Candy for that evolution.';
  end if;
  update public.family_candy set qty = after_qty where user_id = p_uid and family_id = p_family;
  insert into public.candy_ledger (user_id, family_id, amount, type, reason, idempotency, related_catch, qty_before, qty_after)
  values (p_uid, p_family, p_amount, coalesce(p_type, 'CANDY'), p_reason, idem,
          nullif(p_meta->>'catchId', '')::uuid, before_qty, after_qty);
  update public.trainer_stats
     set candy_earned = candy_earned + case when p_amount > 0 then p_amount else 0 end,
         candy_spent = candy_spent + case when p_amount < 0 then abs(p_amount) else 0 end,
         updated_at = now()
   where user_id = p_uid;
  return after_qty;
end;
$function$

CREATE OR REPLACE FUNCTION private.grant_mastery(p_uid uuid, p_dex integer, p_amount integer, p_reason text, p_idem text)
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  pts int;
begin
  if p_uid is null or p_dex is null or coalesce(p_amount, 0) = 0 then
    return coalesce((select points from public.species_mastery where user_id = p_uid and dex = p_dex), 0);
  end if;
  if p_idem is not null and exists (
    select 1 from public.mastery_ledger where user_id = p_uid and idempotency = p_idem
  ) then
    return (select points from public.species_mastery where user_id = p_uid and dex = p_dex);
  end if;
  insert into public.species_mastery (user_id, dex, points, rank)
  values (p_uid, p_dex, 0, 0)
  on conflict do nothing;
  update public.species_mastery
     set points = points + p_amount,
         rank = private.mastery_rank(points + p_amount),
         updated_at = now()
   where user_id = p_uid and dex = p_dex
  returning points into pts;
  insert into public.mastery_ledger (user_id, dex, amount, reason, idempotency)
  values (p_uid, p_dex, p_amount, p_reason, p_idem);
  update public.trainer_stats
     set species_mastered = (select count(*) from public.species_mastery where user_id = p_uid and rank >= 5),
         updated_at = now()
   where user_id = p_uid;
  return pts;
end;
$function$

CREATE OR REPLACE FUNCTION private.process_level_ups(p_uid uuid, p_from integer, p_to integer, p_grant_items boolean DEFAULT true)
 RETURNS void
 LANGUAGE plpgsql
AS $function$
declare
  rec jsonb;
  lvl int;
  key text;
begin
  if p_uid is null or coalesce(p_to, 0) <= coalesce(p_from, 0) then
    return;
  end if;
  for rec in
    select value from jsonb_array_elements(coalesce(private.progression_config()->'levelRewards', '[]'::jsonb))
  loop
    lvl := coalesce((rec->>'level')::int, 0);
    if lvl <= p_from or lvl > p_to then
      continue;
    end if;
    key := 'level:' || lvl::text;
    insert into public.trainer_milestones (user_id, key)
    values (p_uid, key)
    on conflict do nothing;
    if not found then
      continue;
    end if;
    if p_grant_items then
      perform private.grant_progress_rewards(
        p_uid,
        coalesce(rec->'grants', '{}'::jsonb)
          || jsonb_build_object(
            'title', rec->>'title',
            'badge', rec->>'badge',
            'label', coalesce(rec->>'label', 'Trainer Level ' || lvl::text),
            'reason', 'LEVEL_REWARD',
            'idempotency', 'level:' || p_uid::text || ':' || key,
            'key', key
          ),
        true
      );
    else
      if rec ? 'title' then perform private.unlock_title(p_uid, rec->>'title', false); end if;
      if rec ? 'badge' then perform private.unlock_badge(p_uid, rec->>'badge', false); end if;
    end if;
    perform private.push_notice(
      p_uid, 'level',
      'Trainer Level Up!',
      'Level ' || p_from::text || ' → ' || p_to::text,
      jsonb_build_object('from', p_from, 'to', p_to, 'level', lvl, 'reward', rec)
    );
  end loop;
  if not exists (
    select 1 from jsonb_array_elements(coalesce(private.progression_config()->'levelRewards', '[]'::jsonb)) v
    where coalesce((v.value->>'level')::int, 0) > p_from and coalesce((v.value->>'level')::int, 0) <= p_to
  ) and p_to > p_from then
    perform private.push_notice(
      p_uid, 'level',
      'Trainer Level Up!',
      'Level ' || p_from::text || ' → ' || p_to::text,
      jsonb_build_object('from', p_from, 'to', p_to)
    );
  end if;
  perform private.evaluate_cosmetics(p_uid);
end;
$function$

CREATE OR REPLACE FUNCTION private.capture_ball_modifier(p_ball text, p_dex integer, p_owns_species boolean DEFAULT false, p_at timestamp with time zone DEFAULT now(), p_config jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
declare
  cfg jsonb := coalesce(p_config, private.capture_config());
  ctx jsonb := coalesce(cfg->'_context', '{}'::jsonb);
  b public.capture_balls%rowtype;
  s public.species%rowtype;
  mult numeric;
  met boolean := false;
  tier jsonb;
  zone text := coalesce(cfg->>'timezone', 'UTC');
  local_hour int;
  start_hour int;
  end_hour int;
  progress numeric := coalesce((ctx->>'throwProgress')::numeric, 0.5);
  trainer_level int := coalesce((ctx->>'trainerLevel')::int, 1);
  gender text := lower(coalesce(ctx->>'gender', ''));
begin
  if p_ball is null then
    return jsonb_build_object('key', null, 'name', null, 'multiplier', 1.0,
                              'conditionMet', false, 'guaranteed', false, 'condition', 'NONE');
  end if;
  select * into b from public.capture_balls where key = p_ball;
  if not found then
    return jsonb_build_object('key', p_ball, 'name', private.item_label(p_ball), 'multiplier', 1.0,
                              'conditionMet', false, 'guaranteed', false, 'condition', 'UNKNOWN');
  end if;
  select * into s from public.species where dex = p_dex;
  mult := b.base_multiplier;
  case b.condition_type
    when 'TARGET_TYPE' then
      met := coalesce(s.types, '{}'::text[]) && (
        select coalesce(array_agg(value), '{}'::text[])
        from jsonb_array_elements_text(coalesce(b.condition_config->'types', '[]'::jsonb))
      );
    when 'NIGHT' then
      start_hour := coalesce((b.condition_config->>'startHour')::int, 18);
      end_hour := coalesce((b.condition_config->>'endHour')::int, 6);
      local_hour := extract(hour from (p_at at time zone zone))::int;
      met := case
        when start_hour > end_hour then local_hour >= start_hour or local_hour < end_hour
        else local_hour >= start_hour and local_hour < end_hour
      end;
    when 'PLAYER_OWNS_SPECIES' then
      met := coalesce(p_owns_species, false);
    when 'SPECIES_CATCH_RATE_MIN' then
      met := coalesce(s.catch_rate, 0) >= coalesce((b.condition_config->>'min')::int, 999);
    when 'SPECIES_BASE_SPEED_MIN' then
      met := coalesce(s.base_speed, 0) >= coalesce((b.condition_config->>'min')::int, 999);
    when 'MOON_STONE_FAMILY' then
      met := coalesce(s.moon_stone_family, false);
    when 'SPECIES_WEIGHT_TIERS' then
      select t into tier
      from jsonb_array_elements(coalesce(b.condition_config->'tiers', '[]'::jsonb)) t
      where coalesce(s.weight_kg, 0) >= (t->>'minKg')::numeric
      order by (t->>'minKg')::numeric desc
      limit 1;
      if tier is not null then
        met := true;
        mult := (tier->>'multiplier')::numeric;
      end if;
    when 'THROW_EARLY' then
      met := progress <= coalesce((b.condition_config->>'maxProgress')::numeric, 0.34);
    when 'THROW_LATE' then
      met := progress >= coalesce((b.condition_config->>'minProgress')::numeric, 0.66);
    when 'TRAINER_LEVEL_GTE' then
      met := trainer_level >= coalesce((b.condition_config->>'minLevel')::int, 8);
    when 'TARGET_GENDERED' then
      met := gender in ('male', 'female');
    else
      met := false;
  end case;
  if met and b.conditional_multiplier is not null and b.condition_type <> 'SPECIES_WEIGHT_TIERS' then
    mult := b.conditional_multiplier;
  end if;
  return jsonb_build_object(
    'key', b.key, 'name', b.name, 'multiplier', mult,
    'conditionMet', met, 'condition', b.condition_type, 'guaranteed', b.guaranteed_capture
  );
end;
$function$

CREATE OR REPLACE FUNCTION private.grant_known(p_uid uuid, p_grants jsonb)
 RETURNS void
 LANGUAGE plpgsql
AS $function$
declare
  inv public.inventories;
  cap int;
  add_items int;
  add_bonus int;
  extra_add int;
  berry_add int;
  evo_add int;
  val_add int;
  k text;
  n int;
  room int;
  paid_room int;
begin
  inv := private.ensure_inventory(p_uid);
  add_bonus := greatest(coalesce((p_grants->>'bag_bonus')::int, 0), 0);
  paid_room := greatest(0, private.bag_bonus_cap() - coalesce(inv.bag_bonus, 0));
  room := least(private.bag_capacity_max() - private.bag_capacity(p_uid), paid_room);
  if add_bonus > 0 and room <= 0 then
    raise exception 'Bag space upgrades are at the current cap.';
  end if;
  if add_bonus > room then
    add_bonus := greatest(room, 0);
  end if;
  extra_add := coalesce((
    select sum(greatest(coalesce(value::int, 0), 0))
    from jsonb_each_text(coalesce(p_grants, '{}'::jsonb))
    where key = any (private.extra_ball_keys())
  ), 0);
  berry_add := coalesce((
    select sum(greatest(coalesce(value::int, 0), 0))
    from jsonb_each_text(coalesce(p_grants, '{}'::jsonb))
    where key = any (private.capture_berry_keys())
  ), 0);
  evo_add := coalesce((
    select sum(greatest(coalesce(value::int, 0), 0))
    from jsonb_each_text(coalesce(p_grants, '{}'::jsonb))
    where key = any (private.evo_item_keys())
  ), 0);
  val_add := coalesce((
    select sum(greatest(coalesce(value::int, 0), 0))
    from jsonb_each_text(coalesce(p_grants, '{}'::jsonb))
    where key = any (private.valuable_item_keys())
      and key <> all (private.evo_item_keys())
  ), 0);
  add_items := coalesce((p_grants->>'berry')::int, 0)
    + coalesce((p_grants->>'bait')::int, 0)
    + coalesce((p_grants->>'pokeball')::int, 0)
    + coalesce((p_grants->>'greatball')::int, 0)
    + coalesce((p_grants->>'ultraball')::int, 0)
    + coalesce((p_grants->>'lure')::int, 0)
    + extra_add + berry_add + evo_add + val_add;
  cap := private.bag_capacity(p_uid) + add_bonus;
  if private.item_total(inv) + add_items > cap then
    raise exception 'Inventory is full. Buy a Pouch on the Store or use some items first.';
  end if;
  update public.inventories
    set berry = berry + coalesce((p_grants->>'berry')::int, 0),
        bait = bait + coalesce((p_grants->>'bait')::int, 0),
        pokeball = pokeball + coalesce((p_grants->>'pokeball')::int, 0),
        greatball = greatball + coalesce((p_grants->>'greatball')::int, 0),
        ultraball = ultraball + coalesce((p_grants->>'ultraball')::int, 0),
        lure = lure + coalesce((p_grants->>'lure')::int, 0),
        coins = coins + coalesce((p_grants->>'coins')::int, 0),
        bag_bonus = bag_bonus + add_bonus,
        updated_at = now()
    where user_id = p_uid;
  foreach k in array private.extra_ball_keys() loop
    n := coalesce((p_grants->>k)::int, 0);
    if n > 0 then
      update public.inventories
        set balls = jsonb_set(coalesce(balls, '{}'::jsonb), array[k], to_jsonb(coalesce((balls->>k)::int, 0) + n)),
            updated_at = now()
      where user_id = p_uid;
    end if;
  end loop;
  foreach k in array private.capture_berry_keys() loop
    n := coalesce((p_grants->>k)::int, 0);
    if n > 0 then
      update public.inventories
        set berries = jsonb_set(coalesce(berries, '{}'::jsonb), array[k], to_jsonb(coalesce((berries->>k)::int, 0) + n)),
            updated_at = now()
      where user_id = p_uid;
    end if;
  end loop;
  foreach k in array private.evo_item_keys() loop
    n := coalesce((p_grants->>k)::int, 0);
    if n > 0 then
      perform private.adjust_item(p_uid, k, n);
    end if;
  end loop;
  foreach k in array private.valuable_item_keys() loop
    if k = any (private.evo_item_keys()) then
      continue;
    end if;
    n := coalesce((p_grants->>k)::int, 0);
    if n > 0 then
      perform private.adjust_item(p_uid, k, n);
    end if;
  end loop;
end;
$function$

CREATE OR REPLACE FUNCTION private.unlock_badge(p_uid uuid, p_badge text, p_notice boolean DEFAULT true)
 RETURNS boolean
 LANGUAGE plpgsql
AS $function$
declare
  rec public.progression_badges;
begin
  if p_uid is null or coalesce(p_badge, '') = '' then
    return false;
  end if;
  select * into rec from public.progression_badges where id = p_badge and enabled;
  if rec.id is null then
    return false;
  end if;
  insert into public.trainer_badges (user_id, badge_id)
  values (p_uid, rec.id)
  on conflict do nothing;
  if not found then
    return false;
  end if;
  if p_notice then
    perform private.push_notice(p_uid, 'badge', 'Badge unlocked', rec.name,
      jsonb_build_object('badgeId', rec.id, 'name', rec.name));
  end if;
  return true;
end;
$function$

CREATE OR REPLACE FUNCTION private.unlock_title(p_uid uuid, p_title text, p_notice boolean DEFAULT true)
 RETURNS boolean
 LANGUAGE plpgsql
AS $function$
declare
  rec public.progression_titles;
begin
  if p_uid is null or coalesce(p_title, '') = '' then
    return false;
  end if;
  select * into rec from public.progression_titles where id = p_title and enabled;
  if rec.id is null then
    return false;
  end if;
  insert into public.trainer_titles (user_id, title_id)
  values (p_uid, rec.id)
  on conflict do nothing;
  if not found then
    return false;
  end if;
  update public.profiles
     set trainer_title = case when coalesce(trainer_title, '') = '' then rec.name else trainer_title end,
         active_title_id = coalesce(active_title_id, rec.id),
         updated_at = now()
   where id = p_uid;
  if p_notice then
    perform private.push_notice(p_uid, 'title', 'Title unlocked', rec.name,
      jsonb_build_object('titleId', rec.id, 'name', rec.name));
  end if;
  return true;
end;
$function$

CREATE OR REPLACE FUNCTION private.xp_to_reach_level(p_level integer)
 RETURNS integer
 LANGUAGE plpgsql
 STABLE
AS $function$
declare
  total int := 0;
  i int;
  cap int := greatest(1, least(coalesce((private.progression_config()->>'maxLevel')::int, 100), 200));
  target int := greatest(1, least(coalesce(p_level, 1), cap));
begin
  if target <= 1 then
    return 0;
  end if;
  for i in 1 .. target - 1 loop
    total := total + private.xp_for_level(i);
  end loop;
  return total;
end;
$function$

CREATE OR REPLACE FUNCTION private.evaluate_cosmetics(p_uid uuid)
 RETURNS void
 LANGUAGE plpgsql
AS $function$
declare
  rec public.progression_cosmetics;
begin
  if p_uid is null then
    return;
  end if;
  for rec in select * from public.progression_cosmetics where enabled loop
    if rec.starter or private.cosmetic_requirement_met(p_uid, rec.requirement) then
      perform private.unlock_cosmetic(
        p_uid, rec.id,
        case when rec.starter then 'starter' else coalesce(rec.requirement->>'type', 'progress') end,
        not rec.starter
      );
    end if;
  end loop;
end;
$function$

CREATE OR REPLACE FUNCTION private.grant_progress_rewards(p_uid uuid, p_rewards jsonb, p_notice boolean DEFAULT true)
 RETURNS void
 LANGUAGE plpgsql
AS $function$
declare
  reason text := coalesce(p_rewards->>'reason', 'LEVEL_REWARD');
begin
  if p_uid is null or p_rewards is null or p_rewards = '{}'::jsonb then return; end if;
  perform private.grant_items(
    p_uid, coalesce(p_rewards, '{}'::jsonb), reason,
    coalesce(p_rewards->>'key', p_rewards->>'idempotency'),
    coalesce(p_rewards->>'idempotency', 'prog:' || p_uid::text || ':' || coalesce(p_rewards->>'key', 'x')),
    true
  );
  if p_rewards ? 'title' then perform private.unlock_title(p_uid, p_rewards->>'title', p_notice); end if;
  if p_rewards ? 'badge' then perform private.unlock_badge(p_uid, p_rewards->>'badge', p_notice); end if;
  if p_rewards ? 'cosmetic' then
    perform private.unlock_cosmetic(p_uid, p_rewards->>'cosmetic', coalesce(p_rewards->>'key', 'reward'), p_notice);
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION private.adjust_coins(p_uid uuid, p_amount integer, p_type text, p_reason text DEFAULT NULL::text, p_meta jsonb DEFAULT '{}'::jsonb)
 RETURNS integer
 LANGUAGE plpgsql
AS $function$
declare
  before_bal int; after_bal int; idem text := nullif(p_meta->>'idempotency', ''); prior int;
begin
  if p_uid is null then raise exception 'Missing trainer.'; end if;
  if coalesce(p_amount, 0) = 0 then
    select coins into before_bal from public.inventories where user_id = p_uid for update;
    return coalesce(before_bal, 0);
  end if;
  if idem is not null then
    select balance_after into prior from public.coin_ledger where user_id = p_uid and idempotency = idem;
    if found then return prior; end if;
  end if;
  perform private.ensure_inventory(p_uid);
  select coins into before_bal from public.inventories where user_id = p_uid for update;
  after_bal := coalesce(before_bal, 0) + p_amount;
  if after_bal < 0 then raise exception 'Not enough PokéCoins.'; end if;
  update public.inventories set coins = after_bal, updated_at = now() where user_id = p_uid;
  insert into public.coin_ledger (user_id, amount, type, reason, related_item, related_sku, related_round, order_id, idempotency, balance_before, balance_after, detail, economy_version)
  values (
    p_uid,
    p_amount,
    p_type,
    p_reason,
    nullif(p_meta->>'relatedItem',''),
    nullif(p_meta->>'relatedSku',''),
    private.as_uuid_or_null(p_meta->>'relatedRound'),
    private.as_uuid_or_null(p_meta->>'orderId'),
    idem,
    coalesce(before_bal,0),
    after_bal,
    coalesce(p_meta,'{}'::jsonb),
    coalesce((private.economy_config()->>'economyBalanceVersion')::int, 1)
  );
  return after_bal;
exception when unique_violation then
  select balance_after into prior from public.coin_ledger where user_id = p_uid and idempotency = idem;
  return coalesce(prior, 0);
end;
$function$

CREATE OR REPLACE FUNCTION private.grant_items(p_uid uuid, p_grants jsonb, p_reason text, p_source text DEFAULT NULL::text, p_idem text DEFAULT NULL::text, p_strict boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
declare
  grants jsonb := coalesce(p_grants, '{}'::jsonb);
  choice jsonb;
  coins int := 0;
  k text;
  n int;
  given jsonb := '{}'::jsonb;
  full_hit boolean := false;
  round_id text := case
    when private.as_uuid_or_null(p_source) is not null then p_source
    else null
  end;
begin
  if p_uid is null or grants = '{}'::jsonb then
    return jsonb_build_object('ok', true, 'granted', '{}'::jsonb);
  end if;
  if p_idem is not null then
    insert into public.reward_events (user_id, idempotency, reason, source_id, grants)
    values (p_uid, p_idem, coalesce(p_reason, 'GRANT'), p_source, grants)
    on conflict (user_id, idempotency) do nothing;
    if not found then
      return jsonb_build_object('ok', true, 'duplicate', true, 'granted', '{}'::jsonb);
    end if;
  end if;

  choice := grants->'_choice';
  coins := coalesce((grants->>'coins')::int, 0);
  grants := grants - 'coins' - 'title' - 'badge' - 'label' - 'idempotency' - 'key' - '_choice' - 'reason';

  if coalesce((grants->>'choice_stone')::int, 0) > 0 then
    perform private.open_choice_reward(
      p_uid,
      coalesce(p_idem, 'choice-stone:' || p_uid::text || ':' || coalesce(p_source, 'loot')),
      array['firestone','waterstone','thunderstone','leafstone','moonstone'],
      (grants->>'choice_stone')::int
    );
    grants := grants - 'choice_stone';
  end if;
  if choice is not null then
    perform private.open_choice_reward(
      p_uid,
      coalesce(choice->>'reward_key', p_idem, 'choice'),
      coalesce(array(select jsonb_array_elements_text(choice->'options')), array['firestone','waterstone','thunderstone','leafstone','moonstone']),
      greatest(coalesce((choice->>'remaining')::int, 1), 1)
    );
  end if;

  if grants <> '{}'::jsonb then
    begin
      perform private.grant_known(p_uid, grants);
      given := grants;
    exception when others then
      if p_strict or sqlerrm not ilike '%full%' then
        raise;
      end if;
      full_hit := true;
      for k, n in
        select key, greatest(coalesce(value::int, 0), 0)
          from jsonb_each_text(grants)
         where greatest(coalesce(value::int, 0), 0) > 0
      loop
        begin
          perform private.grant_known(p_uid, jsonb_build_object(k, n));
          given := given || jsonb_build_object(k, n);
        exception when others then
          if n > 1 then
            begin
              perform private.grant_known(p_uid, jsonb_build_object(k, 1));
              given := given || jsonb_build_object(k, 1);
            exception when others then
              null;
            end;
          end if;
        end;
      end loop;
      perform private.push_notice(
        p_uid, 'loot', 'Inventory limit reached.',
        'Some rewards could not be added. Use or store items, then keep playing.',
        jsonb_build_object('reason', p_reason)
      );
    end;
  end if;

  if coins <> 0 then
    perform private.adjust_coins(
      p_uid, coins, coalesce(p_reason, 'GRANT'), coalesce(p_reason, 'Reward'),
      jsonb_build_object(
        'idempotency', case when p_idem is null then null else p_idem || ':coins' end,
        'relatedRound', round_id
      )
    );
  end if;

  for k, n in
    select key, greatest(coalesce(value::int, 0), 0)
      from jsonb_each_text(given)
     where greatest(coalesce(value::int, 0), 0) > 0
       and key not in ('coins', 'title', 'badge')
  loop
    insert into public.item_ledger (user_id, item_key, amount, reason, source_id, idempotency)
    values (
      p_uid, k, n, coalesce(p_reason, 'GRANT'), p_source,
      case when p_idem is null then null else p_idem || ':' || k end
    )
    on conflict do nothing;
  end loop;

  if (given ? 'masterball') and coalesce((given->>'masterball')::int, 0) > 0 then
    insert into public.play_console_log (kind, message)
    values (
      'milestone',
      '🏆 ' || coalesce(private.trainer_label(p_uid), 'A trainer') || ' earned a Master Ball!'
    );
  end if;

  return jsonb_build_object('ok', true, 'granted', given, 'full', full_hit, 'coins', coins);
end;
$function$

CREATE OR REPLACE FUNCTION private.store_floors()
 RETURNS jsonb
 LANGUAGE sql
 STABLE
AS $function$
  select coalesce(jsonb_agg(floor order by sort), '[]'::jsonb)
  from (
    select c.sort, jsonb_build_object(
      'id', c.id, 'key', c.key, 'name', c.name, 'blurb', c.blurb,
      'icon', c.icon, 'kind', c.kind, 'system', c.system, 'extra', c.extra,
      'items', coalesce((
        select jsonb_agg(private.store_item_json(i) order by i.sort, i.name)
        from private.store_items i where i.category_id = c.id and private.store_item_is_live(i)
      ), '[]'::jsonb)
    ) as floor
    from private.store_categories c where c.visible
  ) x;
$function$

CREATE OR REPLACE FUNCTION private.adjust_item(p_uid uuid, p_key text, p_delta integer)
 RETURNS integer
 LANGUAGE plpgsql
AS $function$
declare
  before_qty int;
  after_qty int;
begin
  if p_uid is null or coalesce(p_key, '') = '' or coalesce(p_delta, 0) = 0 then
    return private.item_qty(p_uid, p_key);
  end if;
  perform private.ensure_inventory(p_uid);
  select coalesce((items->>p_key)::int, 0) into before_qty
    from public.inventories where user_id = p_uid for update;
  after_qty := before_qty + p_delta;
  if after_qty < 0 then
    raise exception 'You do not have enough of that item.';
  end if;
  update public.inventories
     set items = jsonb_set(coalesce(items, '{}'::jsonb), array[p_key], to_jsonb(after_qty)),
         updated_at = now()
   where user_id = p_uid;
  return after_qty;
end;
$function$

CREATE OR REPLACE FUNCTION private.open_choice_reward(p_uid uuid, p_key text, p_options text[], p_remaining integer)
 RETURNS void
 LANGUAGE plpgsql
AS $function$
begin
  if p_uid is null or coalesce(p_key, '') = '' or coalesce(p_remaining, 0) < 1 then
    return;
  end if;
  insert into public.reward_choices (user_id, reward_key, options, remaining)
  values (p_uid, p_key, coalesce(p_options, array['firestone','waterstone','thunderstone','leafstone','moonstone']), p_remaining)
  on conflict (user_id, reward_key) do update
    set remaining = public.reward_choices.remaining + excluded.remaining,
        options = excluded.options;
  perform private.push_notice(
    p_uid, 'choice', 'Choose a reward',
    'Pick ' || p_remaining::text || ' Evolution Stone' || case when p_remaining = 1 then '' else 's' end || '.',
    jsonb_build_object('rewardKey', p_key, 'remaining', p_remaining)
  );
end;
$function$

CREATE OR REPLACE FUNCTION private.cosmetic_requirement_met(p_uid uuid, p_req jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE
AS $function$
declare
  kind text := lower(coalesce(p_req->>'type', 'starter'));
  n int := coalesce((p_req->>'value')::int, 0);
  xp int := 0;
begin
  if p_uid is null then
    return false;
  end if;
  if kind in ('starter', '') then
    return true;
  elsif kind = 'level' then
    select private.trainer_level(p.xp) into xp from public.profiles p where p.id = p_uid;
    return coalesce(xp, 1) >= n;
  elsif kind = 'unique_species' then
    return (select count(distinct dex) from public.catches where user_id = p_uid) >= n;
  elsif kind = 'shiny_species' then
    return (select count(distinct dex) from public.catches where user_id = p_uid and variant like '%shiny%') >= n;
  elsif kind = 'evolutions' then
    return coalesce((select evolved from public.trainer_stats where user_id = p_uid), 0) >= n;
  elsif kind = 'achievement' then
    return exists (
      select 1 from public.trainer_achievements
      where user_id = p_uid and achievement_id = p_req->>'id' and unlocked_at is not null
    );
  elsif kind = 'store' then
    return private.owns_avatar_pack(p_uid, p_req->>'id');
  elsif kind = 'admin' then
    return exists (
      select 1 from public.trainer_cosmetics tc
      where tc.user_id = p_uid and tc.cosmetic_id = p_req->>'id'
    );
  end if;
  return false;
end;
$function$

CREATE OR REPLACE FUNCTION private.unlock_cosmetic(p_uid uuid, p_id text, p_source text DEFAULT 'progress'::text, p_notice boolean DEFAULT true)
 RETURNS boolean
 LANGUAGE plpgsql
AS $function$
declare
  rec public.progression_cosmetics;
begin
  if p_uid is null or coalesce(p_id, '') = '' then
    return false;
  end if;
  select * into rec from public.progression_cosmetics where id = p_id and enabled;
  if rec.id is null then
    return false;
  end if;
  insert into public.trainer_cosmetics (user_id, cosmetic_id, source)
  values (p_uid, rec.id, coalesce(nullif(p_source, ''), 'progress'))
  on conflict do nothing;
  if not found then
    return false;
  end if;
  if p_notice and not rec.starter then
    perform private.push_notice(
      p_uid, 'unlock',
      'NEW TRAINER REWARD!',
      rec.name,
      jsonb_build_object(
        'cosmeticId', rec.id,
        'kind', rec.kind,
        'name', rec.name,
        'description', rec.description,
        'asset', private.cosmetic_asset(rec.id),
        'equip', true
      )
    );
  end if;
  return true;
end;
$function$

CREATE OR REPLACE FUNCTION private.as_uuid_or_null(p_text text)
 RETURNS uuid
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
begin
  if p_text is null or btrim(p_text) = '' then
    return null;
  end if;
  if p_text !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
    return null;
  end if;
  return p_text::uuid;
exception when others then
  return null;
end;
$function$

CREATE OR REPLACE FUNCTION private.item_identity(p_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
declare
  k text := lower(btrim(coalesce(p_key, '')));
  b public.capture_balls%rowtype;
  berry public.capture_berries%rowtype;
  collector boolean := false;
  best text := '';
  player text := '';
begin
  if k = '' then return null; end if;
  if k = 'bait' then
    return jsonb_build_object(
      'key', 'bait', 'name', 'Honey', 'category', 'community', 'rarity', 'common',
      'collector', false, 'powerLabel', 'COMMUNITY',
      'bestUse', 'Contribute during the item phase so every participating Trainer gets a shared catch boost.',
      'playerText', 'Honey is community catch support. Contributing improves the shared encounter effort. It is not a Berry.',
      'adminText', 'honeyMult 1.00–1.22× from participation + 1.03× if this Trainer contributed.',
      'effect', 1, 'condition', 'COMMUNITY_HONEY', 'storeAvailable', true
    );
  end if;
  if k = 'lure' then
    return jsonb_build_object(
      'key', 'lure', 'name', 'Poké Radar', 'category', 'special', 'rarity', 'uncommon',
      'collector', false, 'powerLabel', 'UTILITY',
      'bestUse', 'Auto-join encounters for 30 minutes.',
      'playerText', 'Automatically joins you to encounters for 30 minutes.',
      'adminText', 'lure timer, not a catch modifier.',
      'effect', 1, 'condition', 'NONE', 'storeAvailable', true
    );
  end if;
  if k = 'bag_bonus' then
    return jsonb_build_object(
      'key', 'bag_bonus', 'name', 'Bag space', 'category', 'special', 'rarity', 'uncommon',
      'collector', false, 'powerLabel', 'UTILITY',
      'bestUse', 'Permanently add bag slots so you can carry more items.',
      'playerText', 'Adds extra bag space forever. This is not an encounter item.',
      'adminText', 'inventories.bag_bonus',
      'effect', 1, 'condition', 'NONE', 'storeAvailable', true
    );
  end if;
  if k = 'rarecandy' then
    return jsonb_build_object(
      'key', 'rarecandy', 'name', 'Rare Candy', 'category', 'evolution', 'rarity', 'rare',
      'collector', false, 'powerLabel', 'PROGRESSION',
      'bestUse', 'Convert into 1 Evolution Candy for a chosen Evolution Line.',
      'playerText', 'Converts into 1 Evolution Candy at the Evolution Center. It does not evolve a Pokémon by itself.',
      'adminText', 'play_use_rare_candy +1 family candy.',
      'effect', 1, 'condition', 'NONE', 'storeAvailable', false
    );
  end if;
  if k in ('firestone','waterstone','thunderstone','leafstone','moonstone','linkingcord') then
    return jsonb_build_object(
      'key', k,
      'name', initcap(replace(replace(k, 'stone', ' Stone'), 'linkingcord', 'Linking Cord')),
      'category', 'evolution', 'rarity', case when k = 'linkingcord' then 'rare' else 'uncommon' end,
      'collector', false, 'powerLabel', 'EVOLUTION',
      'bestUse', 'Use at the Evolution Center on an eligible Pokémon.',
      'playerText', case when k = 'linkingcord'
        then 'Lets Kadabra, Machoke, Graveler, or Haunter evolve without a trade.'
        else 'Evolves certain Pokémon at the Evolution Center when you also have enough Evolution Candy.'
      end,
      'adminText', 'evolution_rules.required_item',
      'effect', 1, 'condition', 'NONE', 'storeAvailable', true
    );
  end if;
  select * into b from public.capture_balls where key = k;
  if found then
    collector := b.condition_type = 'NONE' and coalesce(b.base_multiplier, 1) <= 1.0 and not b.guaranteed_capture
      and coalesce(b.economic_tier, '') in ('collector', 'cosmetic');
    if b.guaranteed_capture then
      best := 'Use when you cannot risk an escape.';
      player := 'Always catches. Not sold on the ordinary shelf.';
    elsif collector then
      best := 'Choose this Ball for its look. Catch power matches a Poké Ball.';
      player := coalesce(nullif(b.description, ''), 'Collector Ball. Same catch power as a Poké Ball.');
    elsif b.condition_type = 'TARGET_TYPE' then
      best := 'Best against ' || array_to_string(array(select jsonb_array_elements_text(coalesce(b.condition_config->'types','[]'::jsonb))), ' / ') || '-type Pokémon.';
      player := best || ' Ordinary against other types.';
    elsif b.condition_type = 'NIGHT' then
      best := 'Best at night on the stream clock.';
      player := 'Stronger at night. Ordinary during the day.';
    elsif b.condition_type = 'PLAYER_OWNS_SPECIES' then
      best := 'Best against a species you have already caught.';
      player := 'Stronger if this species is already in your collection. Ordinary on a first catch.';
    elsif b.condition_type = 'THROW_EARLY' then
      best := 'Best when you choose your Ball immediately in the throw phase.';
      player := 'Stronger if you commit early. Ordinary if you wait.';
    elsif b.condition_type = 'THROW_LATE' then
      best := 'Best when the throw phase is almost over.';
      player := 'Stronger later in the throw phase. Ordinary if you throw immediately.';
    elsif b.condition_type = 'TRAINER_LEVEL_GTE' then
      best := 'Best for experienced Trainers (Lv. ' || coalesce(b.condition_config->>'minLevel', '8') || '+).';
      player := 'Stronger once you reach that Trainer level. Ordinary before then.';
    elsif b.condition_type = 'TARGET_GENDERED' then
      best := 'Best against Pokémon that have a gender.';
      player := 'Stronger on male or female Pokémon. Ordinary on genderless Pokémon.';
    elsif b.condition_type = 'SPECIES_CATCH_RATE_MIN' then
      best := 'Best against common, easily caught Pokémon.';
      player := 'Stronger on common species. Ordinary on rare targets.';
    elsif b.condition_type = 'SPECIES_BASE_SPEED_MIN' then
      best := 'Best against very fast Pokémon.';
      player := 'Stronger on high-Speed species. Ordinary otherwise.';
    elsif b.condition_type = 'MOON_STONE_FAMILY' then
      best := 'Best against Moon Stone evolution families.';
      player := 'Stronger on Clefairy, Nidoran, and other Moon Stone relatives.';
    elsif b.condition_type = 'SPECIES_WEIGHT_TIERS' then
      best := 'Best against very heavy Pokémon.';
      player := 'Stronger as weight increases. Ordinary on light Pokémon.';
    else
      best := coalesce(nullif(b.description, ''), 'A general-purpose Poké Ball.');
      player := best;
    end if;
    return jsonb_build_object(
      'key', b.key, 'name', b.name, 'category', 'balls',
      'rarity', coalesce(b.rarity, 'common'),
      'collector', collector,
      'powerLabel', private.item_power_label(coalesce(b.conditional_multiplier, b.base_multiplier), b.guaranteed_capture, collector),
      'basePower', private.item_power_label(b.base_multiplier, false, collector),
      'bestUse', best,
      'playerText', player,
      'adminText', format('base %s× cond %s %s× guaranteed %s',
        b.base_multiplier, b.condition_type, coalesce(b.conditional_multiplier, b.base_multiplier), b.guaranteed_capture),
      'effect', coalesce(b.conditional_multiplier, b.base_multiplier),
      'baseEffect', b.base_multiplier,
      'condition', b.condition_type,
      'storeAvailable', coalesce(b.store_enabled, true),
      'shopPrice', b.shop_price
    );
  end if;
  select * into berry from public.capture_berries where key = k;
  if found then
    player := coalesce(nullif(berry.rpg_description, ''), berry.canonical_flavor_text, 'A Berry used during the item phase.');
    return jsonb_build_object(
      'key', berry.key, 'name', berry.name, 'category', 'berries',
      'rarity', coalesce(berry.rarity, berry.tier, 'common'),
      'collector', false,
      'powerLabel', private.item_power_label(berry.capture_multiplier, false, false),
      'bestUse', case
        when coalesce(berry.reward_bonus, 0) > 0 then 'Use when you want a catch assist plus extra coins on a successful catch.'
        when berry.capture_multiplier >= 1.25 then 'Rare catch help. Save it for Pokémon you really want.'
        when berry.capture_multiplier >= 1.12 then 'Dependable catch help.'
        else 'Cheap, common catch help.'
      end,
      'playerText', player,
      'adminText', format('capture %s× rewardBonus %s capture_enabled %s', berry.capture_multiplier, berry.reward_bonus, berry.capture_enabled),
      'effect', berry.capture_multiplier,
      'rewardBonus', berry.reward_bonus,
      'condition', 'PREPARE',
      'storeAvailable', berry.store_available,
      'shopPrice', berry.shop_price
    );
  end if;
  return jsonb_build_object('key', k, 'name', initcap(k), 'category', 'special', 'playerText', 'A Trainer item.');
end;
$function$
